(()=>{const main=document.getElementById("main");if(main?.hasAttribute("data-server-rendered")){const answer=main.querySelector("#prerender");main.innerHTML="\n  <div class=\"wrap\">\n\n    <section class=\"hero-intro\" id=\"hero-intro\">\n      <h1>Ask &amp; search the record</h1>\n    </section>\n\n    <!-- ============================== ASK ============================== -->\n    <section id=\"panel-ask\" class=\"panel\" aria-label=\"Ask the record\">\n      <nav class=\"entry-modes\" aria-label=\"Research mode\"><a href=\"/ask\" aria-current=\"page\">Ask a question</a><a href=\"/ask?view=search\" data-entry-mode=\"search\">Find records</a></nav>\n      <form id=\"ask-form\" class=\"ask-row\" data-ui-size=\"large\">\n        <label for=\"ask-input\" class=\"visually-hidden\">Ask a question of the parliamentary record</label>\n        <!-- The box and its clear cross share one wrapper so the cross can sit\n             inside the field at any width; the wrapper takes the row rules the\n             bare textarea used to. -->\n        <div class=\"ask-field ui-input-wrap\">\n          <textarea id=\"ask-input\" class=\"grow-field ui-input\" rows=\"1\" autocomplete=\"off\" enterkeyhint=\"search\" spellcheck=\"false\"></textarea>\n          <button type=\"button\" class=\"field-clear ui-button ui-icon-button\" id=\"ask-clear\" aria-label=\"Clear the question\" data-variant=\"quiet\"><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"m5 5 10 10M15 5 5 15\"/></svg></button>\n        </div>\n        <button type=\"submit\" class=\"ui-button\" id=\"ask-submit\" data-variant=\"primary\">Ask the record</button>\n        <div class=\"ask-options-wrap\">\n        <button type=\"button\" class=\"ui-button\" id=\"ask-options-btn\" aria-expanded=\"false\" aria-controls=\"ask-options-pop\">\n          <span class=\"options-word\">Options</span><svg class=\"btn-icon\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M3 6h14M6 10h8M9 14h2\"/></svg>\n        </button>\n      <div class=\"ask-options-pop\" data-ui-size=\"default\" id=\"ask-options-pop\" hidden>\n        <div class=\"filter-rail ask-pop-rail\">\n          <span class=\"filter-item filter-item-wide ui-field\">\n            <label for=\"a-from\">Years <b id=\"a-years-label\">1993–2026</b></label>\n            <span class=\"range-row\"><span class=\"range-cap\" aria-hidden=\"true\">From</span><input id=\"a-from\" type=\"range\" min=\"1993\" max=\"2026\" value=\"1993\" aria-label=\"From year\"></span>\n            <span class=\"range-row\"><span class=\"range-cap\" aria-hidden=\"true\">To</span><input id=\"a-to\" type=\"range\" min=\"1993\" max=\"2026\" value=\"2026\" aria-label=\"To year\"></span>\n          </span>\n          <span class=\"filter-item ui-field\">\n            <label for=\"a-speaker\">Speaker</label>\n            <input id=\"a-speaker\" type=\"text\" autocomplete=\"off\" placeholder=\"any\" list=\"speakers-list\" class=\"ui-input\">\n          </span>\n          <span class=\"filter-item ui-field\">\n            <label for=\"a-party\">Party</label>\n            <select id=\"a-party\" class=\"ui-input\">\n              <option value=\"\">any</option>\n              <option>Labor</option><option>Liberal</option><option>Nationals</option>\n              <option>LNP</option><option>Greens</option><option>Independent</option>\n              <option>One Nation</option>\n            </select>\n          </span>\n          <span class=\"filter-item ui-field\">\n            <label for=\"a-state\">Parliament</label>\n            <select id=\"a-state\" class=\"ui-input\">\n              <option value=\"\">any</option>\n              <option value=\"federal\">Federal</option><option value=\"nsw\">NSW</option>\n              <option value=\"vic\">VIC</option><option value=\"sa\">SA</option>\n              <option value=\"qld\">QLD</option><option value=\"act\">ACT</option>\n            </select>\n          </span>\n          <span class=\"filter-item ui-field\">\n            <label for=\"a-topic\">Topic</label>\n            <select id=\"a-topic\" class=\"ui-input\">\n              <option value=\"\">any</option>\n              <!-- topics injected from TOPICS in app.js -->\n            </select>\n          </span>\n          <label class=\"ask-scope ui-choice\"><input type=\"checkbox\" id=\"ask-wide\" checked>\n            Search all records, including political funding, contracts and grants</label>\n        </div>\n      </div>\n      </div>\n      </form>\n      <!-- Which filters are on, outside the popover that set them. This row\n           holds its line whether or not anything is set, so a chip arriving\n           never shoves the answer below it down. -->\n      <div id=\"ask-filter-chips\" class=\"filter-chips\" role=\"group\" aria-label=\"Active filters\"></div>\n      <!-- Sample questions as plain links, without a label (the home page's rule). -->\n      <div id=\"ask-chips\" hidden>\n        <div class=\"ask-samples\" id=\"chip-row\" role=\"group\" aria-label=\"Sample questions\"></div>\n      </div>\n      <!-- A question, assembled: a shape to choose, slots to fill from the\n           record's own names. It writes the question the free box would take,\n           so everything after it (the address, the cache, the answer) is the\n           same. app.js renders the sentence per shape (ASK_SHAPES). Closed by\n           default, as on the home page: the free box comes first. -->\n      <details class=\"ask-guided\" id=\"ask-guided\">\n      <summary>Build a question</summary>\n      <section id=\"ask-builder\" class=\"ask-builder\" aria-labelledby=\"ask-builder-head\">\n        <div class=\"ask-builder-modes\" data-ui-size=\"default\">\n          <label id=\"ask-builder-head\" for=\"ask-builder-mode\">Ask about</label>\n          <div class=\"ask-builder-shapes ui-segmented\" role=\"group\" aria-labelledby=\"ask-builder-head\"></div>\n          <select id=\"ask-builder-mode\" class=\"ui-input\"></select>\n        </div>\n        <form id=\"ask-builder-form\" class=\"ask-builder-form\">\n          <p class=\"ask-builder-sentence\" id=\"ask-builder-sentence\"></p>\n          <button type=\"submit\" class=\"primary\" id=\"ask-builder-submit\">Ask this</button>\n        </form>\n        <datalist id=\"ask-topics-list\"></datalist>\n        <datalist id=\"ask-bills-list\"></datalist>\n      </section>\n      </details>\n      <div id=\"ask-status\" class=\"status\" role=\"status\"></div>\n      <div id=\"ask-wombat\" hidden></div>\n      <!-- The passage behind the part of the answer being read, fading up on\n           the right as the reader scrolls. Content duplicates the sources\n           list below; the card is mouse-only (keyboard readers use the list). -->\n      <aside id=\"quote-rail\" class=\"quote-rail\" aria-label=\"Passage from the record behind this part of the answer\" hidden>\n        <!-- Before the reader scrolls the same slot carries the people whose\n             speeches the answer rests on; it duplicates the sources list, so\n             it stays out of the accessibility tree like the card below it. -->\n        <div id=\"people-card\" class=\"people-card record-rule\" aria-hidden=\"true\"></div>\n        <a id=\"quote-card\" class=\"quote-card record-rule\" href=\"#\" tabindex=\"-1\"></a>\n      </aside>\n      <div id=\"ask-result\" hidden>\n        <p class=\"kicker\">Answer</p>\n        <div id=\"ask-overview\" class=\"answer-overview\" hidden></div>\n        <article id=\"ask-answer\" class=\"answer\" tabindex=\"-1\"></article>\n        <p class=\"answer-stamp\" id=\"ask-stamp\"></p>\n        <!-- A question the speeches cannot answer (a count or total of donors,\n             donations, grants or contracts) points at the registers that can. -->\n        <p class=\"ask-register-note\" id=\"ask-register-note\" hidden></p>\n        <div class=\"action-row\">\n          <button type=\"button\" class=\"ui-button\" id=\"ask-copylink\"><svg class=\"btn-icon\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8.3 11.7l3.4-3.4\"/><path d=\"M9.2 13.6l-1.7 1.7a2.85 2.85 0 0 1-4-4l2.5-2.5a2.85 2.85 0 0 1 4 0\"/><path d=\"M10.8 6.4l1.7-1.7a2.85 2.85 0 0 1 4 4L14 11.2a2.85 2.85 0 0 1-4 0\"/></svg><span>Copy link</span></button>\n          <!-- The format is a menu (the search page's sort-menu idiom), not a\n               browser prompt: usable on a phone keyboard and by keyboard. -->\n          <div class=\"search-sort-picker export-picker\" id=\"ask-export-picker\">\n            <button type=\"button\" class=\"search-sort-trigger ui-button\" id=\"ask-export\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"ask-export-menu\"><svg class=\"btn-icon\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M10 3v9\"/><path d=\"M6.5 8.5L10 12l3.5-3.5\"/><path d=\"M3.5 15.5h13\"/></svg><span>Download sources</span><svg class=\"search-sort-chevron\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\"><path d=\"m5 7 5 5 5-5\"/></svg></button>\n            <div id=\"ask-export-menu\" class=\"search-sort-menu\" role=\"menu\" aria-label=\"Download format\" hidden>\n              <button type=\"button\" role=\"menuitem\" data-format=\"csv\" tabindex=\"-1\"><span><strong>CSV</strong><small>A spreadsheet of the sources</small></span></button>\n              <button type=\"button\" role=\"menuitem\" data-format=\"bibtex\" tabindex=\"-1\"><span><strong>BibTeX</strong><small>For LaTeX and reference managers</small></span></button>\n              <button type=\"button\" role=\"menuitem\" data-format=\"ris\" tabindex=\"-1\"><span><strong>RIS</strong><small>For Zotero, EndNote and Mendeley</small></span></button>\n            </div>\n          </div>\n        </div>\n        <!-- The conversation, inline: the follow-ups the Worker wrote from this\n             answer's passages as buttons, and a field for the reader's own. Either\n             carries the question and answer into a thread (openConversationFrom)\n             and asks there; there is no button to go and find the thread first. -->\n        <section id=\"ask-keep\" class=\"ask-keep\" aria-label=\"Keep asking\" hidden>\n          <section id=\"ask-followups\" class=\"chat-next\" aria-label=\"Suggested follow-up questions\" hidden></section>\n          <form id=\"ask-keep-form\" class=\"ask-keep-form\">\n            <label for=\"ask-keep-input\" class=\"visually-hidden\">Ask a follow-up question</label>\n            <input id=\"ask-keep-input\" type=\"text\" autocomplete=\"off\" enterkeyhint=\"send\" placeholder=\"Ask a follow-up…\" class=\"ui-input\">\n            <button type=\"submit\" class=\"ui-button\" data-variant=\"primary\">Ask</button>\n          </form>\n        </section>\n<details id=\"ask-sources\" class=\"chat-sources\" hidden>\n          <summary id=\"ask-sources-sum\">Sources</summary>\n          <p id=\"ask-calculation-note\" class=\"fineprint\" hidden>OPAX calculated these totals from selected public disclosure records. Open a source to explore the supporting funding records. Receipts include more than gifts, and this selection does not cover every donor.</p>\n          <div id=\"ask-date-ruler\" class=\"date-ruler\" hidden></div>\n          <ol id=\"ask-cited-list\" class=\"source-list\"></ol>\n          <details id=\"ask-retrieved\" hidden>\n            <summary>Also retrieved, not cited in the answer</summary>\n            <ol id=\"ask-retrieved-list\" class=\"source-list\"></ol>\n          </details>\n          <p id=\"ask-retrieval-note\" class=\"fineprint\">Answers are written only from the passages retrieved above,\n          and currently draw on the speech corpus. If the record is thin, the answer says so.\n          Answers may be cached. Cite the sources, not this text.\n          <a href=\"/methods\">How answers work</a></p>\n        </details>\n        <!-- The example questions come back under the answer, so a reader who\n             has one answer has somewhere to go besides the follow-ups. -->\n        <section id=\"ask-again\" class=\"chat-next ask-again\" aria-label=\"Ask something else\" hidden>\n          <h3 class=\"subject-section-title\">Ask something else</h3>\n          <div class=\"ask-samples\" id=\"ask-again-row\"></div>\n        </section>\n      </div>\n      <!-- The figures follow the answer: the reader asked a question, so the\n           answer is what they came for. The panel draws on local data and is\n           ready first, but arriving above the answer it pushed the answer\n           below the fold. -->\n      <div id=\"ask-money\" hidden></div>\n\n      <nav id=\"home-tasks\" class=\"home-tasks\" aria-label=\"Start investigating\">\n        <a href=\"/subject/topic\"><strong>Browse a topic</strong><span>The debate and its history.</span></a>\n        <a href=\"/subject/person\"><strong>Find a parliamentarian</strong><span>Speeches, votes and interests.</span></a>\n        <a href=\"/money\"><strong>Follow the money</strong><span>Explore the connections in 3D.</span></a>\n        <a href=\"/bills\"><strong>Understand a bill</strong><span>What changes and where it stands.</span></a>\n      </nav>\n      <section class=\"front-map\" id=\"front-map\" aria-label=\"Explore the money map\">\n        <div class=\"home-map-stage\"><div id=\"front-map-root\" class=\"front-map-root\"><p class=\"status\">Loading the money map…</p></div><div class=\"home-map-invite\"><div class=\"home-map-journeys\"><span>Start a guided journey</span><a href=\"/money?journey=public-money\">Contracts &amp; grants</a><a href=\"/money?journey=multiple-parties\">More than one party</a><a href=\"/money?journey=industry\">Explore an industry</a><a href=\"/money?journey=over-time\">Turn back the clock</a></div><a class=\"home-map-open ui-button\" href=\"/money\" data-variant=\"primary\">Open the research map</a></div></div>\n        <nav class=\"ui-map-filters home-map-industries\" data-ui-size=\"compact\" id=\"front-map-chips\" aria-label=\"Industries on the money map\"></nav>\n      </section>\n      <div class=\"front-grid\" id=\"front-page\">\n        <div class=\"front-main\">\n<section class=\"front-mod\" aria-labelledby=\"h-bills\" id=\"mod-bills\" hidden>\n          <h2 class=\"subject-section-title\" id=\"h-bills\">Latest bills</h2>\n          <ul class=\"subject-list front-bills\" id=\"front-bills\" role=\"list\"></ul>\n          <p class=\"fineprint\" id=\"front-bills-note\">Summaries are written by a model from each bill's explanatory\n          memorandum; they are not the record. <a href=\"/bills\">All bills, with their divisions and speeches →</a></p>\n        </section>\n<section class=\"front-mod\" aria-labelledby=\"h-mw\" id=\"mod-mw\" hidden>\n          <h2 class=\"subject-section-title\" id=\"h-mw\">Money &amp; words</h2>\n          <div id=\"front-mw\"></div>\n        </section>\n<section class=\"front-mod\" aria-labelledby=\"h-added\" id=\"mod-added\" hidden>\n          <h2 class=\"subject-section-title\" id=\"h-added\">Just added to the record</h2>\n          <div class=\"split-list\" id=\"front-added\"></div>\n          <p class=\"fineprint\">The newest documents to enter the index. The corpus updates as\n          parliaments publish.</p>\n          <p style=\"margin:0.6rem 0 0\"><a class=\"search-everything ui-button\" href=\"/ask?view=search\"><svg class=\"btn-icon\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"9\" cy=\"9\" r=\"5.2\"/><path d=\"M13 13l4 4\"/></svg><span>Search everything</span></a></p>\n        </section>\n<section class=\"front-mod\" aria-labelledby=\"h-declared\" id=\"mod-declared\" hidden>\n          <h2 class=\"subject-section-title\" id=\"h-declared\">Just declared</h2>\n          <div id=\"front-declared\"></div>\n          <p class=\"fineprint\"><a href=\"/declared\">All recent declarations →</a></p>\n        </section>\n<section class=\"front-mod\" aria-labelledby=\"h-reports\" id=\"mod-reports\" hidden>\n          <h2 class=\"subject-section-title\" id=\"h-reports\">Reports</h2>\n          <p class=\"fineprint\" style=\"margin:-0.2rem 0 0.6rem\">Long-running investigations pairing\n          the money with the words, every claim cited.</p>\n          <div class=\"report-cards\" id=\"front-reports\"></div>\n        </section>\n        </div>\n        <aside class=\"front-rail\">\n        <section class=\"front-mod home-parliaments\" aria-label=\"Parliamentary record by state\">\n          <div id=\"front-statemap\" class=\"front-map-root\"><p class=\"status\">Loading the map…</p></div>\n        </section>\n        <section class=\"front-mod\" aria-labelledby=\"h-numbers\">\n          <h2 class=\"subject-section-title\" id=\"h-numbers\">Today's numbers</h2>\n          <div class=\"tiles tiles-compact\" id=\"front-numbers\"></div>\n          <p class=\"fineprint\" id=\"front-numbers-note\">Live from the search index.\n          <a href=\"/stats\">Full corpus breakdown</a></p>\n        </section>\n<section class=\"front-mod\" aria-labelledby=\"h-ency\" id=\"mod-ency\" hidden>\n          <h2 class=\"subject-section-title\" id=\"h-ency\">From the encyclopedia</h2>\n          <div class=\"entry-stack\" id=\"front-ency\"></div>\n          <p class=\"fineprint\">From AEC disclosures and the speech index. Totals are a floor, not a ceiling.</p>\n        </section>\n<section class=\"front-mod\" aria-labelledby=\"h-ways\">\n          <h2 class=\"subject-section-title\" id=\"h-ways\">More ways in</h2>\n          <div class=\"entry-stack\">\n            <a class=\"report-card\" href=\"/money\">\n              <span class=\"front-way-heading\"><svg class=\"card-glyph\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"6\" cy=\"7\" r=\"3\"/><circle cx=\"18\" cy=\"5\" r=\"2\"/><circle cx=\"15\" cy=\"18\" r=\"4\"/><path d=\"m8 9 4.5 6M17.5 7l-1.7 7\"/></svg><span class=\"card-kicker\">Interactive</span></span>\n              <span class=\"card-title\">The money map</span>\n              <span class=\"card-blurb\">250 donors, 11 parties, 28 years of AEC returns, as territory you can spin.</span>\n              <span class=\"card-meta\">Open →</span>\n            </a>\n            <a class=\"report-card\" href=\"/bills\">\n              <span class=\"front-way-heading\"><svg class=\"card-glyph\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7\"/></svg><span class=\"card-kicker\">Encyclopedia</span></span>\n              <span class=\"card-title\">Bills</span>\n              <span class=\"card-blurb\">Every federal bill since 2013: what it changes, who it affects, how the parties divided.</span>\n              <span class=\"card-meta\">Open →</span>\n            </a>\n            <a class=\"report-card\" href=\"/explore\">\n              <span class=\"front-way-heading\"><svg class=\"card-glyph\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 11a9 9 0 1 1 2.6 7.4M3 4v7h7M12 7v6l4 2\"/></svg><span class=\"card-kicker\">Explore</span></span>\n              <span class=\"card-title\">Time machine</span>\n              <span class=\"card-blurb\">Dial up any year since 1998 and see what parliament was arguing about.</span>\n              <span class=\"card-meta\">Open →</span>\n            </a>\n            <a class=\"report-card\" href=\"/explore\">\n              <span class=\"front-way-heading\"><svg class=\"card-glyph\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 3h14v18H5zM9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 16v.2\"/></svg><span class=\"card-kicker\">Explore</span></span>\n              <span class=\"card-title\">The record quiz</span>\n              <span class=\"card-blurb\">Guess what the numbers say, then see the receipts.</span>\n              <span class=\"card-meta\">Open →</span>\n            </a>\n          </div>\n        </section>\n        </aside>\n                                              </div>\n    </section>\n\n    <!-- ============================= SEARCH ============================ -->\n    <section id=\"panel-chat\" class=\"panel\" hidden aria-label=\"Keep asking\">\n      <div class=\"dock-bar\">\n        <span class=\"dock-mark\" aria-hidden=\"true\"></span>\n        <span class=\"dock-title\">Ask the record</span>\n        <button type=\"button\" class=\"dock-icon ui-button ui-icon-button\" id=\"dock-new\" title=\"Start a new conversation\" aria-label=\"Start a new conversation\" data-variant=\"quiet\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\"/></svg>\n        </button>\n        <button type=\"button\" class=\"dock-icon ui-button ui-icon-button\" id=\"dock-expand\" title=\"Open the full conversation\" aria-label=\"Open the full conversation\" data-variant=\"quiet\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14 4h6v6M20 4l-8 8M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5\"/></svg>\n        </button>\n        <button type=\"button\" class=\"dock-icon ui-button ui-icon-button\" id=\"dock-close\" aria-label=\"Close the assistant\" data-variant=\"quiet\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m6 6 12 12M18 6 6 18\"/></svg>\n        </button>\n      </div>\n      <!-- The conversation's own chrome, outside the scroller: the way out of\n           it, and whose record it is held with when it is held with one\n           person's (written by renderChatScope). Docked it sits under the bar,\n           so the thread fades under it rather than taking it with them; on\n           /chat the scroller is display:contents and this is the page's own\n           head, pinned under the masthead. -->\n      <div class=\"chat-head\">\n        <p class=\"kicker\">Keep asking</p>\n        <button type=\"button\" class=\"ui-button\" id=\"chat-new\">Start a new conversation</button>\n        <p class=\"chat-scope\" id=\"chat-scope\" hidden></p>\n      </div>\n      <div class=\"chat-scroll\" id=\"chat-scroll\">\n        <div id=\"chat-history\" class=\"chat-history\" hidden></div>\n        <div id=\"chat-thread\" class=\"chat-thread\" aria-label=\"Conversation with the record\"></div>\n        <div id=\"chat-status\" class=\"status\" role=\"status\"></div>\n      </div>\n      <form id=\"chat-form\" class=\"chat-composer\">\n        <input type=\"text\" id=\"chat-input\" autocomplete=\"off\" placeholder=\"Ask a follow-up question…\"\n               aria-label=\"Ask a follow-up question\" class=\"ui-input\">\n        <button type=\"button\" class=\"chat-mic ui-button ui-icon-button\" id=\"chat-mic\" title=\"Talk to OPAX · 10 minutes free\" aria-label=\"Talk to OPAX, 10 minutes free\" data-variant=\"quiet\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0V5ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8\"/></svg>\n        </button>\n        <button type=\"submit\" class=\"ui-button\" id=\"chat-send\" data-variant=\"primary\">Ask</button>\n      </form>\n    </section>\n\n    <section id=\"panel-search\" class=\"panel\" hidden aria-label=\"Search the record\">\n      <h1 class=\"visually-hidden\">Search all public records</h1>\n      <nav class=\"entry-modes\" aria-label=\"Research mode\"><a href=\"/ask\" data-entry-mode=\"ask\">Ask a question</a><a href=\"/ask?view=search\" aria-current=\"page\">Find records</a></nav>\n      <form id=\"search-form\" class=\"search-grid\">\n        <div class=\"query-line\" data-ui-size=\"large\">\n          <label for=\"search-input\" class=\"visually-hidden\">Find source records</label>\n          <textarea id=\"search-input\" class=\"grow-field ui-input\" rows=\"1\" autocomplete=\"off\" enterkeyhint=\"search\" spellcheck=\"false\" placeholder=\"Search the record…\"></textarea>\n          <button type=\"submit\" class=\"ui-button\" data-variant=\"primary\">Search</button>\n          <div class=\"ask-options-wrap\">\n          <button type=\"button\" class=\"ui-button\" id=\"search-options-btn\" aria-expanded=\"false\" aria-controls=\"search-options-pop\">\n            <span class=\"options-word\">Filters</span><svg class=\"btn-icon\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M3 6h14M6 10h8M9 14h2\"/></svg>\n          </button>\n          <dialog class=\"ask-options-pop\" data-ui-size=\"default\" id=\"search-options-pop\" hidden aria-labelledby=\"search-options-title\">\n            <div class=\"search-sheet-head\"><h2 id=\"search-options-title\" class=\"subject-section-title\">Search filters</h2><button type=\"button\" class=\"ui-button ui-icon-button\" id=\"search-options-close\" aria-label=\"Close search filters\">Close</button></div>\n            <div class=\"filter-rail ask-pop-rail\">\n              <span class=\"filter-item filter-item-wide ui-field\">\n                <!-- The matches by year, as the year facet: a band sets the years. -->\n                <span id=\"search-date-ruler\" class=\"date-ruler\" hidden></span>\n                <span class=\"search-years-heading\">Years <b id=\"f-years-label\">1993–2026</b></span>\n                <span class=\"search-year-fields\"><label>From year<select id=\"f-from\" aria-label=\"From year\" class=\"ui-input\"></select></label><label>To year<select id=\"f-to\" aria-label=\"To year\" class=\"ui-input\"></select></label></span>\n              </span>\n              <span class=\"filter-item ui-field\">\n                <label for=\"f-speaker\">Speaker</label>\n                <input id=\"f-speaker\" type=\"text\" autocomplete=\"off\" placeholder=\"any\" list=\"speakers-list\" class=\"ui-input\">\n              </span>\n              <span class=\"filter-item ui-field\">\n                <label for=\"f-party\">Party</label>\n                <select id=\"f-party\" class=\"ui-input\">\n                  <option value=\"\">any</option>\n                  <option>Labor</option><option>Liberal</option><option>Nationals</option>\n                  <option>LNP</option><option>Greens</option><option>Independent</option>\n                  <option>One Nation</option><option>Centre Alliance</option>\n                  <option>Katter's Australian Party</option><option>United Australia Party</option>\n                  <option>Australian Democrats</option><option>Country Liberal Party</option>\n                  <option>Family First</option><option>DLP</option><option>JLN</option>\n                </select>\n              </span>\n              <span class=\"filter-item ui-field\">\n                <label for=\"f-state\">Jurisdiction</label>\n                <select id=\"f-state\" class=\"ui-input\">\n                  <option value=\"\">any</option>\n                  <option value=\"federal\">Federal</option><option value=\"nsw\">NSW</option>\n                  <option value=\"vic\">VIC</option><option value=\"sa\">SA</option>\n                  <option value=\"qld\">QLD</option><option value=\"tas\">TAS</option><option value=\"wa\">WA</option><option value=\"nt\">NT</option><option value=\"act\">ACT</option>\n                </select>\n              </span>\n              <span class=\"filter-item ui-field\">\n                <label for=\"f-topic\">Topic</label>\n                <select id=\"f-topic\" class=\"ui-input\">\n                  <option value=\"\">any</option>\n                  <!-- topics injected from TOPICS in app.js -->\n                </select>\n              </span>\n              <span class=\"filter-item ui-field\">\n                <label for=\"search-kind\">Record type</label>\n                <select id=\"search-kind\" class=\"ui-input\">\n                  <option value=\"all\">All records</option>\n                  <option value=\"person\">People</option>\n                  <option value=\"party\">Political parties</option>\n                  <option value=\"donor\">Donors</option>\n                  <option value=\"receipt\">Political receipts</option>\n                  <option value=\"supplier\">Suppliers</option>\n                  <option value=\"agency\">Government agencies</option>\n                  <option value=\"contract\">Government contracts</option>\n                  <option value=\"grant\">Grants</option>\n                  <option value=\"interest\">Declared interests</option>\n                  <option value=\"expense\">Parliamentary expenses</option>\n                  <option value=\"pay\">Parliamentary pay</option>\n                  <option value=\"access\">Meetings and lobbying registers</option>\n                  <option value=\"campaigner\">Campaigners and associated entities</option>\n                  <option value=\"bill\">Bills</option>\n                  <option value=\"speech\">Speeches and hearings</option>\n                  <option value=\"division\">Divisions (recorded votes)</option>\n                  <option value=\"press_release\">Government transcripts and releases</option>\n                  <option value=\"report\">Research reports</option>\n                  <option value=\"audit report\">Audit reports</option>\n                  <option value=\"grant_invitation\">Grant invitations</option>\n                  <option value=\"grant_award\">Grant award source records</option>\n                  <option value=\"election_baseline\">Election baselines</option>\n                  <option value=\"parliamentary_profile\">Recorded representation</option>\n                  <option value=\"research_report\">Research source notes</option>\n                </select>\n              </span>\n              <span class=\"filter-item ui-field\">\n                <label for=\"search-mode\">Mode</label>\n                <select id=\"search-mode\" class=\"ui-input\">\n                  <option value=\"hybrid\">Meaning and words</option>\n                  <option value=\"semantic\">Match meaning</option>\n                  <option value=\"keyword\">Match words</option>\n                </select>\n              </span>\n            </div>\n            <div class=\"search-sheet-foot\"><button type=\"button\" class=\"ui-button\" id=\"search-options-reset\">Reset filters</button><button type=\"button\" class=\"ui-button\" id=\"search-options-apply\" data-variant=\"primary\">Apply filters</button></div>\n          </dialog>\n          </div>\n        </div>\n      </form>\n\n      <!-- Which filters are on, outside the popover that set them. Rendered\n           before the fetch resolves, so it never shifts the results below.\n           Empty means no filters, and an empty row folds away in CSS. -->\n      <div id=\"search-filter-chips\" class=\"filter-chips\" role=\"group\" aria-label=\"Active filters\"></div>\n\n      <nav id=\"search-chips\" class=\"chip-row search-chips\" aria-label=\"Example searches\" hidden></nav>\n      <div id=\"search-status\" class=\"status\" role=\"status\"></div>\n      <div id=\"search-wombat\" hidden></div>\n      <div class=\"search-results-grid\">\n      <div class=\"search-results-main\">\n      <div id=\"search-empty\" class=\"empty-state\" hidden></div>\n      <div class=\"results-bar\" id=\"results-bar\" hidden>\n        <span class=\"results-lead\">\n          <span class=\"results-summary\">\n            <span id=\"results-count\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></span>\n            <span id=\"search-brief-status\" class=\"search-brief-status\" aria-live=\"polite\"></span>\n          </span>\n        </span>\n        <div class=\"results-actions\">\n          <div id=\"search-readbar\" class=\"search-readbar\" hidden>\n            <div class=\"ui-segmented\" role=\"group\" aria-label=\"Search result text\">\n              <button type=\"button\" id=\"search-read-passages\" aria-pressed=\"true\" class=\"ui-button\">Passages</button>\n              <button type=\"button\" id=\"search-read-briefs\" aria-pressed=\"false\" class=\"ui-button\">Briefs</button>\n            </div>\n            <!-- With Briefs on, the list's one machine label. -->\n            <details class=\"ui-pop ui-machine search-briefs-label\" id=\"search-briefs-label\" hidden><summary><span class=\"ui-machine-glyph\" aria-hidden=\"true\">✦</span>Machine-written</summary><div class=\"ui-sheet\"><p>Briefs are written by a model from each record. A brief is not part of the record: open the record to read it. A row with no brief shows the record’s own text.</p></div></details>\n          </div>\n          <div id=\"search-sort-picker\" class=\"search-sort-picker\">\n            <input id=\"search-sort\" type=\"hidden\" value=\"relevance\">\n            <button type=\"button\" class=\"search-sort-trigger ui-button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"search-sort-menu\" aria-label=\"Sort matches: Relevance\">\n              <svg class=\"btn-icon\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M3 5h14M3 10h10M3 15h6\"/></svg><span class=\"search-sort-label\">Relevance</span><svg class=\"search-sort-chevron\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\"><path d=\"m5 7 5 5 5-5\"/></svg>\n            </button>\n            <div id=\"search-sort-menu\" class=\"search-sort-menu\" role=\"menu\" aria-label=\"Sort matches\" aria-describedby=\"search-sort-note\" hidden>\n              <button type=\"button\" role=\"menuitemradio\" aria-checked=\"true\" data-value=\"relevance\" tabindex=\"-1\"><span><strong>Relevance</strong><small>Closest matches to your search</small></span><span class=\"search-sort-check\" aria-hidden=\"true\">✓</span></button>\n              <button type=\"button\" role=\"menuitemradio\" aria-checked=\"false\" data-value=\"newest\" tabindex=\"-1\"><span><strong>Newest first</strong><small>Most recent dated records</small></span><span class=\"search-sort-check\" aria-hidden=\"true\">✓</span></button>\n              <button type=\"button\" role=\"menuitemradio\" aria-checked=\"false\" data-value=\"oldest\" tabindex=\"-1\"><span><strong>Oldest first</strong><small>Earliest dated records</small></span><span class=\"search-sort-check\" aria-hidden=\"true\">✓</span></button>\n              <button type=\"button\" role=\"menuitemradio\" aria-checked=\"false\" data-value=\"title_asc\" tabindex=\"-1\"><span><strong>Title A–Z</strong><small>Alphabetical by title or name</small></span><span class=\"search-sort-check\" aria-hidden=\"true\">✓</span></button>\n              <button type=\"button\" role=\"menuitemradio\" aria-checked=\"false\" data-value=\"title_desc\" tabindex=\"-1\"><span><strong>Title Z–A</strong><small>Reverse alphabetical order</small></span><span class=\"search-sort-check\" aria-hidden=\"true\">✓</span></button>\n              <button type=\"button\" role=\"menuitemradio\" aria-checked=\"false\" data-value=\"type\" tabindex=\"-1\"><span><strong>Record type</strong><small>Group the different datasets</small></span><span class=\"search-sort-check\" aria-hidden=\"true\">✓</span></button>\n              <p id=\"search-sort-note\">Applies across all pages of retrieved matches.</p>\n            </div>\n          </div>\n          <!-- ⋯: copy the link and the three export formats. A details popover;\n               ui-source.js gives it Escape and light dismiss. -->\n          <details class=\"ui-pop ui-more\" id=\"search-more\">\n            <summary aria-label=\"Share and export these results\" title=\"Share and export these results\"><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><circle cx=\"4.5\" cy=\"10\" r=\"1.5\"/><circle cx=\"10\" cy=\"10\" r=\"1.5\"/><circle cx=\"15.5\" cy=\"10\" r=\"1.5\"/></svg></summary>\n            <div class=\"ui-sheet\">\n              <ul class=\"ui-more-list\" role=\"list\">\n                <li><button type=\"button\" class=\"ui-more-item\" id=\"search-copylink\"><span>Copy link</span></button></li>\n                <li><button type=\"button\" class=\"ui-more-item\" data-format=\"csv\"><span>Export CSV</span><small>A spreadsheet of every retrieved match</small></button></li>\n                <li><button type=\"button\" class=\"ui-more-item\" data-format=\"bibtex\"><span>Export BibTeX</span><small>For LaTeX and reference managers</small></button></li>\n                <li><button type=\"button\" class=\"ui-more-item\" data-format=\"ris\"><span>Export RIS</span><small>For Zotero, EndNote and Mendeley</small></button></li>\n              </ul>\n            </div>\n          </details>\n        </div>\n      </div>\n      <!-- Summarise these records: a collapsed row with the machine label. It\n           is written on request, when the row is opened, and sits above the\n           results it reads. -->\n      <details class=\"search-answer\" id=\"search-answer\" hidden>\n        <summary class=\"search-summary-row\"><span class=\"search-summary-word\" id=\"search-answer-head\">Summarise these records</span><span class=\"ui-machine-pill\"><span class=\"ui-machine-glyph\" aria-hidden=\"true\">✦</span>Machine-written</span></summary>\n        <div class=\"search-summary-open\">\n          <p class=\"search-summary-status\" id=\"search-answer-status\" role=\"status\" aria-live=\"polite\"></p>\n          <div class=\"answer answer-compact\" id=\"search-answer-body\"></div>\n          <details id=\"search-answer-fold\" class=\"chat-sources\" hidden>\n            <summary id=\"search-answer-sum\">Sources</summary>\n            <ol class=\"source-list\" id=\"search-answer-sources\"></ol>\n          </details>\n          <p class=\"search-summary-note\" id=\"search-answer-more\"></p>\n          <button type=\"button\" class=\"ui-button\" id=\"search-answer-retry\" hidden>Try summary again</button>\n        </div>\n      </details>\n      <ul id=\"search-results\" class=\"results\" role=\"list\"></ul>\n      <!-- The band keeps its height whether or not there is a second page, so\n           arriving at a short last page does not lift the footer. -->\n      <nav id=\"search-pager\" class=\"pager\" aria-label=\"Result pages\" hidden>\n        <button type=\"button\" class=\"pager-btn ui-button\" id=\"pager-prev\">\n          <svg class=\"btn-icon\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 4l-6 6 6 6\"/></svg><span class=\"pager-btn-label\">Previous</span></button>\n        <!-- app.js fills this: how many numbers there are, and which runs of\n             pages are elided, depends on how many pages the result has. -->\n        <div class=\"pager-pages\" id=\"pager-pages\"></div>\n        <button type=\"button\" class=\"pager-btn ui-button\" id=\"pager-next\">\n          <span class=\"pager-btn-label\">Next</span><svg class=\"btn-icon\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 4l6 6-6 6\"/></svg></button>\n        <!-- The numbers carry this on screen; spoken, it is what changes when\n             the reader turns the page. -->\n        <span class=\"visually-hidden\" id=\"pager-where\" role=\"status\"></span>\n      </nav>\n      </div>\n\n      </div>\n    </section>\n\n    <!-- ============================ MONEY MAP ========================== -->\n    <section id=\"panel-money\" class=\"panel\" hidden aria-label=\"Money map\">\n      <h1 class=\"visually-hidden\">3D connections</h1>\n      <div data-money-navigation></div>\n      <div class=\"money-workspace-toolbar\">\n        <div id=\"money-jur\"></div>\n        <details id=\"money-journey-picker\" class=\"journey-menu\" name=\"money-tools\"><summary>Guided journeys</summary><div id=\"money-journey-controls\"></div></details>\n        <div id=\"money-research\"></div>\n        <!-- ⋯: the full-screen map and the agency maps. Programs & places is a tab already. -->\n        <details class=\"ui-pop ui-more\" id=\"money-more\"><summary aria-label=\"More money tools\" title=\"More money tools\"><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><circle cx=\"4.5\" cy=\"10\" r=\"1.5\"/><circle cx=\"10\" cy=\"10\" r=\"1.5\"/><circle cx=\"15.5\" cy=\"10\" r=\"1.5\"/></svg></summary>\n          <div class=\"ui-sheet\"><ul class=\"ui-more-list\" role=\"list\">\n            <li><a class=\"ui-more-item\" href=\"/map\" data-full-map>Full-screen map</a></li>\n            <li><a class=\"ui-more-item\" href=\"/subject/agency\">Agency contract maps</a></li>\n          </ul></div></details>\n      </div>\n      <div id=\"money-stage\" class=\"money-stage\">\n        <aside id=\"money-journey-story\" class=\"journey-story\" aria-label=\"Guided journey\" hidden></aside>\n        <div id=\"money-map-root\" class=\"money-map-root\"></div>\n      </div>\n      <div id=\"money-research-results\"></div>\n      <!-- The map's one source line (moneyFineprintHTML in app.js). -->\n      <div id=\"money-fineprint\" class=\"money-source\"></div>\n    </section>\n\n    <section id=\"panel-money-records\" class=\"panel\" hidden aria-label=\"Money records\"><div data-money-navigation></div><h1 class=\"visually-hidden\" id=\"money-records-title\">Political receipts</h1><div id=\"money-records-body\"></div></section>\n    <!-- ========================= CONNECTIONS ========================== -->\n    <!-- Organisations, programs and places named across the collected records.\n         connections.js mounts into #connections-body when the route opens and\n         tears itself down when it leaves (see openConnectionsPage in app.js). -->\n    <section id=\"panel-connections\" class=\"panel\" hidden aria-labelledby=\"connections-title\">\n      <div data-money-navigation></div>\n      <div id=\"connections-body\" class=\"supplier-page connections-page\">\n        <!-- The Money sub-nav tab \"Programs &amp; places\" already names this view; the heading stays for assistive tech, the page title and focus on arrival. -->\n        <h1 id=\"connections-title\" class=\"visually-hidden\" tabindex=\"-1\">Connections in the record</h1>\n        <p class=\"connections-lede\">Explore organisations, programs and places across speeches, official releases and grant records.</p>\n        <div class=\"ui-toolbar\">\n          <label class=\"ui-field\">Find a connection<input class=\"ui-input\" id=\"connection-search\" type=\"search\" placeholder=\"Name, program or electorate\" autocomplete=\"off\"></label>\n          <label class=\"ui-field\">Show<select class=\"ui-input\" id=\"connection-kind\"><option value=\"\">Everything</option><option value=\"organisation\">Organisations</option><option value=\"program\">Programs</option><option value=\"electorate\">Electorates</option><option value=\"place\">Places</option></select></label>\n        </div>\n        <p id=\"connection-status\" role=\"status\">Opening the records…</p>\n        <div class=\"connections-layout\">\n          <div id=\"connection-list\"></div>\n          <section id=\"connection-detail\" tabindex=\"-1\" aria-label=\"Selected connection\" hidden></section>\n        </div>\n      </div>\n    </section>\n    <!-- ============================= REPORTS =========================== -->\n    <section id=\"panel-reports\" class=\"panel\" hidden aria-label=\"Reports\">\n      <!-- The index: one title, the cards, one dated source line for the set. -->\n      <div id=\"reports-index\">\n        <div class=\"subject-head reports-head\">\n          <h2 id=\"reports-title\" tabindex=\"-1\">Reports</h2>\n          <p class=\"subject-tag\"><span>Standing investigations that pair the money with the words, every claim cited to the record.</span></p>\n        </div>\n        <div id=\"reports-list\" class=\"report-cards\"></div>\n        <div id=\"reports-source\"></div>\n      </div>\n      <div id=\"reports-status\" class=\"status\" role=\"status\"></div>\n      <article id=\"report-view\" hidden>\n        <h2 id=\"report-title\" tabindex=\"-1\"></h2>\n        <p id=\"report-blurb\" class=\"report-blurb\"></p>\n        <!-- v2 head: the window the report covers and the lede in reading\n             size. Empty and hidden for a v1 report. -->\n        <div id=\"report-head2\" class=\"report-head2\" hidden></div>\n        <!-- The nav is a child of the article, not of the head: a sticky\n             element is bounded by its containing block, and inside the head it\n             would unpin one line later. -->\n        <nav id=\"report-jump\" class=\"report-jump\" hidden aria-label=\"Parts of this report\"></nav>\n        <p id=\"report-meta\" class=\"report-meta\"></p>\n        <div class=\"report-lead\" id=\"report-lead\">\n          <div id=\"report-brief\"></div>\n          <aside id=\"report-figures\"></aside>\n        </div>\n        <!-- v2 parts, in reading order, ahead of the money a v1 page also has. -->\n        <section id=\"report-now\" class=\"report-part\" hidden aria-labelledby=\"report-now-head\"></section>\n        <section id=\"report-overtime\" class=\"report-part\" hidden aria-labelledby=\"report-overtime-head\"></section>\n        <section id=\"report-money\" class=\"report-part\" hidden aria-labelledby=\"report-money-head\"></section>\n        <div id=\"report-stats\"></div>\n        <div id=\"report-positions\"></div>\n        <div id=\"report-moments\"></div>\n        <div id=\"report-sections\"></div>\n        <div id=\"report-allsources\" hidden></div>\n        <!-- v2 keeps its provenance at the foot, beside the data it describes. -->\n        <p id=\"report-meta2\" class=\"report-meta report-foot-meta\" hidden></p>\n        <div id=\"report-download\"></div>\n      </article>\n    </section>\n\n    <!-- ============================== DOC ============================== -->\n    <section id=\"panel-doc\" class=\"panel\" hidden aria-label=\"Document from the record\">\n      <div class=\"doc-head\">\n        <h2 id=\"doc-title\" tabindex=\"-1\"></h2>\n        <p id=\"doc-topic\" class=\"doc-topic\" hidden></p>\n        <p id=\"doc-meta\" class=\"doc-meta\"></p>\n        <nav id=\"doc-topics\" class=\"doc-topics\" aria-label=\"Topics this speech is labelled with\" hidden></nav>\n        <div class=\"doc-toolbar\" id=\"doc-actions\" hidden>\n          <div class=\"doc-toolbar-btns\" role=\"group\" aria-label=\"Document actions\" data-ui-size=\"compact\">\n            <a class=\"ui-button\" data-variant=\"primary\" id=\"doc-ask\" href=\"/ask\">Ask the record about this</a>\n            <button type=\"button\" class=\"ui-button\" id=\"doc-profile\" aria-label=\"Full profile\">Profile</button>\n            <button type=\"button\" class=\"ui-button\" id=\"doc-cite\" aria-expanded=\"false\" aria-controls=\"doc-cite-panel\">Cite</button>\n            <button type=\"button\" class=\"ui-button\" id=\"doc-more\">Speeches</button>\n            <button type=\"button\" class=\"ui-button\" id=\"doc-similar\" aria-label=\"Find similar speeches\" aria-expanded=\"false\" aria-controls=\"doc-similar-panel\">Similar</button>\n            <button type=\"button\" class=\"ui-button\" id=\"doc-copylink\">Copy link</button>\n          </div>\n          <p id=\"doc-speaker-links\" class=\"fineprint doc-speaker-links\" hidden></p>\n        </div>\n      </div>\n      <!-- A speech whose debate is exactly one bill in /bills/index.json gets\n           the bill's dated status and its first summary sentence, quietly,\n           under the byline. No match, no panel: it never guesses. -->\n      <aside id=\"doc-bill\" class=\"doc-bill\" aria-labelledby=\"doc-bill-head\" hidden></aside>\n      <div id=\"doc-cite-panel\" class=\"cite-panel\" hidden>\n        <!-- injected -->\n      </div>\n      <section id=\"doc-similar-panel\" aria-label=\"Similar speeches\" hidden></section>\n      <hr class=\"ledger-rule doc-rule\">\n      <div id=\"doc-status\" class=\"status\" role=\"status\"></div>\n      <!-- The summary is OPAX's writing, the record below is parliament's. They\n           were the same serif at the same size, told apart only by a grey line\n           between them, which is not a difference a reader should have to look\n           for on a site whose whole claim is the record's own words. -->\n      <div class=\"doc-reading-layout\">\n      <aside id=\"doc-brief\" class=\"doc-brief\" aria-labelledby=\"doc-brief-head\" hidden>\n        <div class=\"doc-brief-head\">\n          <h3 class=\"subject-section-title\" id=\"doc-brief-head\">In brief</h3>\n        </div>\n        <p id=\"doc-brief-text\"></p>\n        <p class=\"doc-brief-note\">Written from this speech by a model, not by a person, and not part of the record.</p>\n      </aside>\n      <div id=\"doc-text\" class=\"doc-text\"></div>\n      </div>\n      <p class=\"fineprint\" id=\"doc-caveat\" hidden></p>\n      <!-- A speech can run to tens of thousands of pixels on a phone, so the\n           actions a reader wants once they have read it wait at the end too. -->\n      <div class=\"doc-toolbar doc-toolbar-foot\" id=\"doc-foot-actions\" hidden>\n        <div class=\"doc-toolbar-btns\" role=\"group\" aria-label=\"Document actions, repeated at the end\" data-ui-size=\"compact\">\n          <a class=\"ui-button\" data-variant=\"primary\" id=\"doc-ask-foot\" href=\"/ask\">Ask the record about this</a>\n          <button type=\"button\" class=\"ui-button\" id=\"doc-cite-foot\">Cite</button>\n          <button type=\"button\" class=\"ui-button\" id=\"doc-similar-foot\" aria-label=\"Find similar speeches\">Similar</button>\n          <button type=\"button\" class=\"ui-button\" id=\"doc-copylink-foot\">Copy link</button>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"panel-discover\" class=\"panel\" hidden aria-labelledby=\"discover-title\">\n      <h1 class=\"visually-hidden\" id=\"discover-title\">Government contracts</h1>\n      <div data-money-navigation></div>\n      <div class=\"discovery-view-control\">\n        <label for=\"discover-categories\">View</label>\n        <select id=\"discover-categories\">\n          <option value=\"procurement_concentration\">Contracts by agency</option>\n          <option value=\"recipient_concentration\">Party funding</option>\n          <option value=\"donor_contract_overlap\">Companies in both</option>\n        </select>\n      </div>\n      <div class=\"discovery-workspace\">\n        <aside class=\"discovery-browser\" aria-label=\"Choose a comparison\">\n          <label id=\"discover-query-label\" for=\"discover-query\">Find an agency or company</label>\n          <input id=\"discover-query\" type=\"search\" placeholder=\"Search names\" autocomplete=\"off\">\n          <div class=\"discovery-list-controls\"><p id=\"discover-count\" role=\"status\"></p><label class=\"visually-hidden\" for=\"discover-sort\">Sort comparisons</label><select id=\"discover-sort\"><option value=\"value\">Largest totals</option><option value=\"share\">Biggest share</option></select></div>\n          <p id=\"discover-list-note\" class=\"discovery-list-note\"></p>\n          <div id=\"discover-results\" aria-busy=\"false\"></div>\n        </aside>\n        <div id=\"discover-detail\" class=\"discovery-detail\"></div>\n      </div>\n      <details id=\"discover-methodology\" class=\"discovery-methodology\"><summary>About these numbers</summary><div id=\"discover-methodology-body\"></div></details>\n    </section>\n\n    <!-- ============================ EXPLORE ============================ -->\n    <section id=\"panel-explore\" class=\"panel\" hidden aria-label=\"Explore\">\n      <div class=\"subject-head\">\n        <h2 id=\"explore-title\" tabindex=\"-1\">Explore</h2>\n        <p class=\"subject-tag\"><span>Tools and games built on the public record: speeches, votes, money and grants.</span></p>\n      </div>\n      <div class=\"game-grid\">\n        <button type=\"button\" class=\"game-card\" id=\"explore-ballot-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"10\" y=\"5\" width=\"28\" height=\"38\" rx=\"2\"/><path d=\"M17 14h3v4h-3zM17 25h3v4h-3zM26 16h6M26 27h6M17 36h15\"/></svg></span>\n          <span class=\"game-title\">Build your ballot</span>\n          <span class=\"game-blurb\">Research the candidates and arrange your own preferences with a practice ballot from the 2025 federal election.</span>\n          <span class=\"game-cta\">Build a practice ballot</span>\n        </button>\n        <button type=\"button\" class=\"game-card\" id=\"explore-tm-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"\n                 stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <circle cx=\"24\" cy=\"26\" r=\"15\"/>\n              <path d=\"M24 17v9l6.5 4\"/>\n              <path d=\"M9 10.5L15 6l1 7.5\"/>\n              <path d=\"M39 10.5L33 6l-1 7.5\"/>\n            </svg>\n          </span>\n          <span class=\"game-title\">Time machine</span>\n          <span class=\"game-blurb\">Spin the dial through 29 years and see what parliament\n          was arguing about, with the real speeches to prove it.</span>\n          <span class=\"game-cta\">Play</span>\n        </button>\n        <button type=\"button\" class=\"game-card\" id=\"explore-tide-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"\n                 stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M7 38h34\"/>\n              <path d=\"M10 32V24M19 32V16M28 32V21M37 32V9\"/>\n              <path d=\"M8 20c7-1 10-8 17-7s8 7 15 3\"/>\n            </svg>\n          </span>\n          <span class=\"game-title\">The tide</span>\n          <span class=\"game-blurb\">Twenty-one debates across four decades, sorted by what is\n          rising, fading or largest now—with the labelling coverage in view.</span>\n          <span class=\"game-cta\">Open</span>\n        </button>\n        <button type=\"button\" class=\"game-card\" id=\"explore-quiz-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"\n                 stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M24 5l4.6 9.3 10.3 1.5-7.4 7.3 1.7 10.2L24 28.5l-9.2 4.8 1.7-10.2-7.4-7.3 10.3-1.5z\"/>\n              <path d=\"M18 36.5L15 44M30 36.5L33 44\"/>\n            </svg>\n          </span>\n          <span class=\"game-title\">The record quiz</span>\n          <span class=\"game-blurb\">Eight quick questions computed straight from the public\n          record. Every answer comes with its source.</span>\n          <span class=\"game-cta\">Play</span>\n        </button>\n        <button type=\"button\" class=\"game-card\" id=\"explore-ledger-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"\n                 stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <rect x=\"9\" y=\"6\" width=\"30\" height=\"36\" rx=\"2\"/>\n              <path d=\"M9 14h30M9 22h30M9 30h30\"/>\n              <path d=\"M19 6v36\"/>\n            </svg>\n          </span>\n          <span class=\"game-title\">The ledger</span>\n          <span class=\"game-blurb\">Every disclosed donation flow in one sortable table.\n          Filter it, follow it, take it home as CSV.</span>\n          <span class=\"game-cta\">Open</span>\n        </button>\n        <button type=\"button\" class=\"game-card\" id=\"explore-grants-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"\n                 stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M11 6h19l7 7v29H11z\"/>\n              <path d=\"M30 6v7h7\"/>\n              <path d=\"M17 20h14M17 26h14M17 32h8\"/>\n              <circle cx=\"33\" cy=\"35\" r=\"4.5\"/>\n              <path d=\"M30.5 39l-1.5 5 4-2 4 2-1.5-5\"/>\n            </svg>\n          </span>\n          <span class=\"game-title\">Who gets the grants</span>\n          <span class=\"game-blurb\">Every published grant award, resolved to the organisations that\n          receive it and checked against the donor registers. Programs, seats and the money.</span>\n          <span class=\"game-cta\">Open</span>\n        </button>\n        <button type=\"button\" class=\"game-card\" id=\"explore-matrix-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"\n                 stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <rect x=\"7\" y=\"8\" width=\"34\" height=\"32\" rx=\"2\"/>\n              <path d=\"M7 18.5h34M7 29.5h34\"/>\n              <path d=\"M18.5 8v32M29.5 8v32\"/>\n              <circle cx=\"13\" cy=\"24\" r=\"2.1\" fill=\"currentColor\" stroke=\"none\"/>\n              <circle cx=\"24\" cy=\"34.75\" r=\"2.1\" fill=\"currentColor\" stroke=\"none\"/>\n              <circle cx=\"35.5\" cy=\"13.25\" r=\"2.1\" fill=\"currentColor\" stroke=\"none\"/>\n            </svg>\n          </span>\n          <span class=\"game-title\">Who owns which debate</span>\n          <span class=\"game-blurb\">Every party's share of every debate in one shaded grid,\n          live from the labelled record. Each cell opens the speeches behind it.</span>\n          <span class=\"game-cta\">Open</span>\n        </button>\n        <button type=\"button\" class=\"game-card\" id=\"explore-wd-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"\n                 stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M14 9h27M14 15h15\"/>\n              <path d=\"M14 24h21M14 30h27\"/>\n              <path d=\"M14 39h10M14 45h18\"/>\n              <circle cx=\"7\" cy=\"9\" r=\"2.1\" fill=\"currentColor\" stroke=\"none\"/>\n              <circle cx=\"7\" cy=\"24\" r=\"2.1\" fill=\"currentColor\" stroke=\"none\"/>\n              <circle cx=\"7\" cy=\"39\" r=\"2.1\" fill=\"currentColor\" stroke=\"none\"/>\n            </svg>\n          </span>\n          <span class=\"game-title\">Words per dollar</span>\n          <span class=\"game-blurb\">Each industry's disclosed donations beside each party's\n          share of the matching debate. Comparison, not causation.</span>\n          <span class=\"game-cta\">Open</span>\n        </button>\n        <button type=\"button\" class=\"game-card\" id=\"explore-tvn-btn\">\n          <span class=\"game-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"\n                 stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <rect x=\"5\" y=\"6\" width=\"17\" height=\"27\" rx=\"2\"/>\n              <rect x=\"26\" y=\"15\" width=\"17\" height=\"27\" rx=\"2\"/>\n              <path d=\"M9 13h9M9 19h9M9 25h6\"/>\n              <path d=\"M30 22h9M30 28h9M30 34h6\"/>\n            </svg>\n          </span>\n          <span class=\"game-title\">Then vs now</span>\n          <span class=\"game-blurb\">Pick a speaker and a topic, then read what they said in\n          two eras side by side, with dated quotes from the record.</span>\n          <span class=\"game-cta\">Open</span>\n        </button>\n      </div>\n\n      <dialog class=\"game-dialog\" id=\"dialog-ballot\" aria-label=\"Build your ballot\">\n        <div class=\"game-dialog-head\"><button type=\"button\" class=\"game-close\" data-close=\"dialog-ballot\" aria-label=\"Close\">✕</button></div>\n        <div id=\"explore-ballot\" class=\"game-dialog-body\"></div>\n      </dialog>\n      <dialog class=\"game-dialog\" id=\"dialog-tm\" aria-label=\"Time machine\">\n        <div class=\"game-dialog-head\">\n          <button type=\"button\" class=\"game-close\" data-close=\"dialog-tm\" aria-label=\"Close\">✕</button>\n        </div>\n        <div id=\"explore-tm\" class=\"game-dialog-body\"></div>\n      </dialog>\n      <dialog class=\"game-dialog\" id=\"dialog-tide\" aria-label=\"The tide\">\n        <div class=\"game-dialog-head\">\n          <button type=\"button\" class=\"game-close\" data-close=\"dialog-tide\" aria-label=\"Close\">✕</button>\n        </div>\n        <div id=\"explore-tide\" class=\"game-dialog-body\"></div>\n      </dialog>\n      <dialog class=\"game-dialog\" id=\"dialog-quiz\" aria-label=\"The record quiz\">\n        <div class=\"game-dialog-head\">\n          <button type=\"button\" class=\"game-close\" data-close=\"dialog-quiz\" aria-label=\"Close\">✕</button>\n        </div>\n        <div id=\"explore-quiz\" class=\"game-dialog-body\"></div>\n      </dialog>\n      <dialog class=\"game-dialog\" id=\"dialog-ledger\" aria-label=\"The ledger\">\n        <div class=\"game-dialog-head\">\n          <button type=\"button\" class=\"game-close\" data-close=\"dialog-ledger\" aria-label=\"Close\">✕</button>\n        </div>\n        <div id=\"explore-ledger\" class=\"game-dialog-body\"></div>\n      </dialog>\n      <dialog class=\"game-dialog\" id=\"dialog-grants\" aria-label=\"Who gets the grants\">\n        <div class=\"game-dialog-head\">\n          <button type=\"button\" class=\"game-close\" data-close=\"dialog-grants\" aria-label=\"Close\">✕</button>\n        </div>\n        <div id=\"explore-grants\" class=\"game-dialog-body\"></div>\n      </dialog>\n      <dialog class=\"game-dialog\" id=\"dialog-matrix\" aria-label=\"Who owns which debate\">\n        <div class=\"game-dialog-head\">\n          <button type=\"button\" class=\"game-close\" data-close=\"dialog-matrix\" aria-label=\"Close\">✕</button>\n        </div>\n        <div id=\"explore-matrix\" class=\"game-dialog-body\"></div>\n      </dialog>\n      <dialog class=\"game-dialog\" id=\"dialog-wd\" aria-label=\"Words per dollar\">\n        <div class=\"game-dialog-head\">\n          <button type=\"button\" class=\"game-close\" data-close=\"dialog-wd\" aria-label=\"Close\">✕</button>\n        </div>\n        <div id=\"explore-wd\" class=\"game-dialog-body\"></div>\n      </dialog>\n      <dialog class=\"game-dialog\" id=\"dialog-tvn\" aria-label=\"Then vs now\">\n        <div class=\"game-dialog-head\">\n          <button type=\"button\" class=\"game-close\" data-close=\"dialog-tvn\" aria-label=\"Close\">✕</button>\n        </div>\n        <div id=\"explore-tvn\" class=\"game-dialog-body\"></div>\n      </dialog>\n    </section>\n\n    <!-- ============================ SUBJECT ============================ -->\n    <section id=\"panel-subject\" class=\"panel\" hidden aria-label=\"Subject entry\">\n      <div id=\"subject-body\"><!-- entry injected --></div>\n    </section>\n\n    <!-- ============================== BILLS ============================= -->\n    <!-- One panel serves /bills (the index) and /bill/<key> (one bill): both\n         are the same reading, at two scales, and switching between them should\n         not move the page under the reader. -->\n    <section id=\"panel-bill\" class=\"panel\" hidden aria-label=\"Bills\">\n      <div id=\"bill-body\"><!-- index or bill injected --></div>\n    </section>\n\n    <!-- =========================== DECLARED =========================== -->\n    <section id=\"panel-declared\" class=\"panel\" hidden aria-label=\"Recent alterations to registers of interests\">\n      <h1 tabindex=\"-1\">Registers of interests</h1>\n      <p class=\"lede\">The newest additions and deletions recorded in parliamentarians' registers of interests, in their own words.</p>\n      <form id=\"declared-filters\" class=\"dir-controls ui-toolbar\" aria-label=\"Filter recent declarations\">\n        <span class=\"ui-field dir-field declared-search\">\n          <label for=\"declared-query\">Search</label>\n          <input class=\"ui-input\" id=\"declared-query\" type=\"search\" placeholder=\"Name, organisation or interest…\">\n        </span>\n        <span class=\"ui-field dir-field\">\n          <label for=\"declared-bucket\">Category</label>\n          <select class=\"ui-input\" id=\"declared-bucket\"><option value=\"\">all categories</option></select>\n        </span>\n        <span class=\"ui-field dir-field\">\n          <label for=\"declared-party\">Party</label>\n          <select class=\"ui-input\" id=\"declared-party\"><option value=\"\">all parties</option></select>\n        </span>\n        <button class=\"ui-button\" type=\"submit\">Search</button>\n      </form>\n      <p class=\"interests-summary\" id=\"declared-summary\" hidden></p>\n      <div id=\"declared-pagination\"></div>\n      <div id=\"declared-list\"><p class=\"status\">Opening the register ledger…</p></div>\n      <p class=\"fineprint declared-source\">Sources: <a href=\"https://www.aph.gov.au/Senators_and_Members/Parliamentarian_Search_Results/Registers_of_Interests\" rel=\"noopener\" target=\"_blank\">Registers of Members' and Senators' Interests, 48th Parliament ↗︎</a>, entries as declared, not verified by OPAX; and the <a href=\"https://www.parliament.qld.gov.au/Members/Current-Members/Register-of-Interests\" rel=\"noopener\" target=\"_blank\">Queensland Register of Members' Interests, 58th Parliament ↗︎</a>, facts and links only. Additions and deletions carry the date the register records. A gift or trip with no organisation match names one the AEC and lobbyist registers do not list under that spelling. Organisation matches to <a href=\"https://transparency.aec.gov.au/\" rel=\"noopener\" target=\"_blank\">AEC Transparency Register returns, CC BY 4.0 ↗︎</a>, the lobbyist registers and FITS use exact normalised names.</p>\n    </section>\n\n    <!-- ============================= ABOUT ============================= -->\n    <!-- ============================== STATS ============================ -->\n    <section id=\"panel-stats\" class=\"panel\" hidden aria-label=\"Corpus statistics\">\n      <p class=\"kicker\">The corpus in numbers</p>\n      <div class=\"stat-grid\" id=\"stats-hero\"><!-- filled from corpus.json --></div>\n      <div class=\"corpus-meter\" id=\"corpus-meter\" hidden>\n        <p id=\"corpus-meter-text\"></p>\n        <div class=\"meter-track\" role=\"meter\" aria-valuemin=\"0\" aria-valuemax=\"100\"\n             aria-valuenow=\"0\" aria-label=\"Share of collected speeches indexed\" id=\"corpus-meter-bar\">\n          <i></i>\n        </div>\n      </div>\n      <p class=\"fineprint\" id=\"stats-live\">corpus loading…</p>\n      <section id=\"stats-connections\" class=\"supplier-section\" hidden></section>\n\n      <p class=\"kicker\">In the live index</p>\n      <div class=\"table-scroll\"><table class=\"about-table stats-live-table\">\n        <thead><tr><th>Speeches by parliament</th><th>Speeches</th></tr></thead>\n        <tbody id=\"stats-parliaments\"><tr><td colspan=\"2\">Counting…</td></tr></tbody>\n        <thead><tr><th>Documents by kind</th><th>Documents</th></tr></thead>\n        <tbody id=\"stats-kinds\"><tr><td colspan=\"2\">Counting…</td></tr></tbody>\n      </table></div>\n\n      <p class=\"kicker\">Sources loaded</p>\n      <div class=\"table-scroll\"><table class=\"about-table\">\n        <thead><tr><th>Source</th><th>Documents</th><th>Coverage</th></tr></thead>\n        <tbody id=\"stats-sources\"><!-- filled from corpus.json --></tbody>\n      </table></div>\n      <p class=\"fineprint\" id=\"stats-version\"></p>\n      <p><a href=\"/audit\">Queensland Audit Office reports to Parliament</a> is a separate\n      catalogue of report metadata and HTML recommendations. Source: Queensland Audit Office,\n      <a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>, with State of Queensland\n      attribution and <a href=\"https://www.qao.qld.gov.au/copyright\">per-report exceptions</a>.\n      Its report count is shown in the directory and is separate from corpus document totals.</p>\n      <p class=\"fineprint\">How the corpus is collected and what is known to be missing:\n        <a href=\"/methods\">Methods</a> · <a href=\"/about\">About OPAX</a> · <a href=\"https://x.com/OpaxAustralia\" target=\"_blank\" rel=\"noopener noreferrer\">OPAX on X</a> · <a href=\"https://www.facebook.com/OpaxAustralia/\" target=\"_blank\" rel=\"noopener noreferrer\">OPAX on Facebook</a> · <a href=\"https://www.instagram.com/opaxaustralia/\" target=\"_blank\" rel=\"noopener noreferrer\">OPAX on Instagram</a></p>\n    </section>\n\n    <section id=\"panel-about\" class=\"panel\" hidden aria-label=\"About OPAX\">\n      <!-- At regular width the page's sections are listed beside it (design\n           review: About keeps its prose and gains an index). -->\n      <nav class=\"about-index\" aria-labelledby=\"about-index-head\">\n        <p class=\"about-index-head\" id=\"about-index-head\">On this page</p>\n        <ul role=\"list\">\n          <li><a href=\"#about-use\">What you can do here</a></li>\n          <li><a href=\"#about-record\">The record</a></li>\n          <li><a href=\"#about-money\">The money</a></li>\n          <li><a href=\"#about-votes\">Votes and bills</a></li>\n          <li><a href=\"#about-instruments\">Federal legislative instruments</a></li>\n          <li><a href=\"#about-audit\">Queensland audit reports</a></li>\n          <li><a href=\"#about-people\">People</a></li>\n          <li><a href=\"#about-machines\">Enrichments written by machines</a></li>\n          <li><a href=\"#about-limits\">What this cannot prove</a></li>\n          <li><a href=\"#about-who\">Who makes it</a></li>\n          <li><a href=\"#about-licences\">Licences and reuse</a></li>\n          <li><a href=\"#about-contact\">How to reach us</a></li>\n        </ul>\n      </nav>\n      <div class=\"about-body\">\n      <h2>What OPAX is</h2>\n      <p>OPAX, the Open Parliamentary Accountability Exchange, has one intent: to put as much of\n      the open data about Australian politics as possible in one place, cross-referenced and\n      citable, so that the blind spots become findable. What a politician said on the record, how\n      they voted, what they declared, who gave money to their party, who lobbied whom, which\n      grants and contracts followed: each of these is published somewhere, in its own format,\n      under its own terms, and almost never beside the others. Put side by side, a politician who\n      gives two hundred speeches about a problem but votes against every reform, or an industry\n      that donates millions while its regulation stalls, leaves a paper trail. OPAX makes that\n      trail searchable and citable. It started as speeches and donations; it now also carries the\n      votes those speeches led to, the bills those votes decided, the government grants and\n      contracts that sometimes follow the same money, and the registers that record who lobbies\n      whom. Every claim on the site links back to the primary record it came from, because a\n      blind spot is only worth finding if someone else can check it.</p>\n      <p class=\"fineprint\">OPAX contains the names and images of people who have died.</p>\n\n      <h2 id=\"about-use\">What you can do here</h2>\n      <ul class=\"about-list\">\n        <li><strong>Ask</strong>: put a question to the speech corpus (widen it to the recorded\n        divisions with one checkbox) and get an answer written only from the passages retrieved\n        for it. Every claim is cited; every citation opens the actual speech at a stable, linkable\n        page; if the record is thin on a question, the answer says so.</li>\n        <li><strong>Search</strong>: hybrid semantic and keyword search with reranking, filterable\n        by speaker, party, parliament and year, with citation-ready exports.</li>\n        <li><strong>Money map</strong>: the largest disclosed donors in three dimensions, ringed\n        by industry around the parties they gave to, with a year range you can drag, a words layer\n        showing who speaks on each industry's debates, and a grants layer showing which of those\n        donors also collect government money.</li>\n        <li><strong>Reports</strong>: six standing investigations — climate &amp; energy, gambling,\n        housing, immigration, First Nations and media ownership — drawing on parliamentary debate,\n        government announcements, legislation and financial records, refreshed as the record grows.</li>\n        <li><strong>Explore</strong>: the Time Machine (dial up any year since 1998 and see what\n        parliament was arguing about), the tide (which debates are rising or fading), the record\n        quiz, the ledger (every disclosed donation flow in one exportable table) and who gets the\n        grants.</li>\n        <li><strong>Bills</strong>: a registry of federal bills since 2013, each one linked to the\n        divisions that decided it and the speeches made about it, with a plain-English summary of\n        what its explanatory memorandum says.</li>\n        <li><strong>Encyclopedia</strong>: an entry for every parliamentarian, party, donor and\n        topic, with quick facts, voting record, declared interests, expenses and the money map\n        narrowed to that entity.</li>\n      </ul>\n\n      <h2 id=\"about-record\">The record</h2>\n      <div class=\"table-scroll\"><table class=\"about-table\">\n        <thead><tr><th>Source</th><th>Documents</th><th>Coverage</th></tr></thead>\n        <tbody id=\"about-sources\"><!-- filled from corpus.json --></tbody>\n      </table></div>\n      <p>The last two rows above are not speeches: recorded divisions and AEC donation returns\n      share the corpus's citation and search plumbing, so they are counted here even though the\n      donations themselves are described in full below. The speech rows are filtered to the era of\n      currently serving parliamentarians (13 March 1993 onward), deduplicated across overlapping\n      sources, and stripped of procedural noise (division roll-calls, chair interjections, day\n      indexes). Federal Hansard is Commonwealth copyright, reproduced here under the CC BY-NC-ND\n      terms that cover the official transcript; each state parliament sets its own copyright terms,\n      and OPAX reproduces and cites speeches for research rather than republishing whole documents\n      commercially — check the source link on any document before quoting it commercially.</p>\n      <p class=\"fineprint\">Full detail, model identity and known defects:\n      <a href=\"/methods\">methods &amp; how to cite OPAX</a> · machine-readable manifest:\n      <a href=\"/corpus.json\">corpus.json</a>.</p>\n\n      <h2 id=\"about-money\">The money</h2>\n      <p>Every federal donation disclosed to the AEC since 1998 is loaded — 199,233 rows —\n      and the <a href=\"/money\">money map</a> plots the 250 largest donors against 11 parties as\n      662 flows, built from 127,658 of those rows after excluding public funding, internal party\n      transfers and donations from government-linked entities. Queensland, Victoria and Tasmania\n      publish their own donation registers under an open licence, and OPAX runs the same map over\n      each: Queensland (250 donors, 402 flows from 22,703 gifts), Victoria (250 donors, 291 flows\n      from 3,416 donations) and Tasmania (166 donors, 172 flows from 221 donations, because its\n      disclosure scheme is only a year old). State and federal totals are never added together,\n      because AEC returns already fold in what a party's state branches raised.</p>\n      <p>The newest layer is government grants. Every Commonwealth grant award published on\n      GrantConnect since the register opened at the end of 2017 (360,058 awards, $235.5 billion,\n      CC BY 3.0 AU) and every Queensland Government funding line since 2017-18 (230,007 awards,\n      $85.7 billion, CC BY 4.0) are matched to the donor register by ABN wherever one is published:\n      763 Commonwealth recipients ($26.3 billion, 11% of the register) and 489 Queensland\n      recipients ($3.3 billion, 4%) are also donors. On the money map itself, 30 of the 250 largest\n      federal donors and 27 of the 250 largest Queensland donors also collected grants — $1.0\n      billion and $334 million between them — shown as a toggleable layer with its own flows from\n      a single grantor node. A donor receiving a grant is a fact on the public record, not a\n      finding; the grants explorer states plainly what share of a recipient's dollars arrived while\n      a party it had donated to held office, and nothing stronger.</p>\n      <p>Alongside the donations sit an uncapped roster of 438 associated entities, third parties,\n      significant third parties and political campaigners that raise or spend on politics without\n      being a party — everything above $100,000 in any year from the AEC's own annual returns —\n      and, separately, the parties' own lodged debts and discretionary benefits. Six lobbyist\n      registers (federal, New South Wales, Queensland, Victoria, South Australia and Western\n      Australia) are loaded in full: on the money map, 133 of the 250 largest federal donors also\n      show up as a registered lobbying client or a name in a ministerial diary — 102 as lobbying\n      clients, 92 in one of 61,499 disclosed meetings between ministers and everyone they met,\n      from the New South Wales Cabinet Office and the Queensland Cabinet Office. Queensland alone\n      also publishes who lobbied whom and when: 8,235 logged contacts since September 2016. A\n      separate federal register, the Foreign Influence Transparency Scheme, tracks who works in\n      Australia for a foreign government or political organisation for the purpose of political\n      influence; OPAX carries the whole public register (145 registrants, 728 declared activities)\n      and shows it on any donor, lobbying firm or parliamentarian page it matches, always with the\n      reminder that registering is a legal disclosure, not a finding of wrongdoing.</p>\n      <p class=\"fineprint\">Every donation, meeting and grant figure here is a floor, not a\n      ceiling: disclosure schemes only require reporting above a threshold, so smaller gifts and\n      quieter meetings leave no public trace. New South Wales and South Australia's political\n      donations are not on OPAX at all — New South Wales' own terms forbid automated collection of\n      its disclosure portal, and South Australia banned political donations from 1 July 2025.\n      Western Australia, the ACT and the Northern Territory publish their donations, but under\n      terms that do not permit republishing them here; that data is held for internal research\n      only and nothing from those three jurisdictions appears on the site.</p>\n\n      <h2 id=\"about-votes\">Votes and bills</h2>\n      <p>Every recorded division OPAX could get in a structured form — 13,867 of them, federal\n      divisions from TheyVoteForYou and state divisions parsed from New South Wales, Victorian and\n      Queensland Hansard, 1998 to today — is a citable document in the search index in its own\n      right, and 962 sitting and former parliamentarians (622 federal, 133 New South Wales, 122\n      Victorian, 85 Queensland) carry a voting record on their own page. Most questions in every\n      chamber are decided on the voices and leave no division at all, so \"no recorded vote\" never\n      means \"did not vote\".</p>\n      <p>A federal bill registry now covers every bill introduced from the 43rd Parliament (2013)\n      to today: 2,969 bills, 31,377 progress events and 19,958 links out to the divisions,\n      speeches and Acts that followed from them. 13,949 of those links are speeches that name the\n      bill on a day it was genuinely before the chamber — checked against the bill's own progress\n      record, not guessed from a topic string, because federal Hansard topics from 2013 on carry\n      only the bare word \"Bills\". 1,698 of the 2,969 bills carry a three-sentence, model-written\n      summary of what their explanatory memorandum or Bills Digest says, each one labelled\n      \"written by a model from the explanatory memorandum; not the record\" (a further 812 were\n      generated but held back after failing an automatic check, and are not shown).</p>\n      <p class=\"fineprint\">Two gaps in the underlying speech corpus shape what a bill or a division\n      page can show, and are worth stating plainly. There is no Senate Hansard in the corpus at all\n      for 2014 to 2022, so a bill whose real fight happened in the Senate in that window looks\n      quiet on OPAX no matter how contested it was. And 2024 is thin across the board — federal\n      chamber speeches drop to 82 for the whole year — so the 47th Parliament's bills (2022–2025)\n      reach a linked speech only 24% of the time, against 74–84% in every other parliament since\n      2013. Neither gap is a fault in the bill registry; both close only as more Hansard is loaded.</p>\n\n      <h2 id=\"about-instruments\">Federal legislative instruments</h2>\n      <p>The instruments catalogue carries in-force title metadata\n      from the Office of Parliamentary Counsel's <a href=\"https://www.legislation.gov.au/\">Federal\n      Register of Legislation</a>. OPAX shows titles, dates, departments, portfolios, status and\n      bounded version metadata, with FRL's current/latest flags retained verbatim. The returned\n      version may be earlier than the latest; every page links FRL's authoritative latest text.\n      No document bodies or model summaries appear in this catalogue.\n      Missing commencement dates stay unknown; FRL's in-force listing includes legislation made but\n      not yet commenced. Every detail page links the authoritative text on FRL. Names in instrument\n      titles remain authorised record text and create no person profiles or identity joins.</p>\n\n      <h2 id=\"about-audit\">Queensland audit reports</h2>\n      <p><a href=\"/audit\">Queensland audit reports</a> lists the Queensland Audit Office's\n      reports tabled in Parliament, with report numbers, years, tabled dates, sectors, public\n      bodies identified in the HTML audit scope, PDF links and HTML recommendations\n      with source numbers where published.\n      Recommendations are QAO's text. Missing HTML fields stay unknown. PDF bodies, entity\n      responses and the app surface are phase 2. No person profiles or joins are created.</p>\n      <p>Source: Queensland Audit Office, <a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>.\n      © The State of Queensland (Queensland Audit Office) 2026. Each report page is checked for\n      <a href=\"https://www.qao.qld.gov.au/copyright\">copyright exceptions</a>; excepted bodies\n      are withheld. Metadata is arranged into a catalogue and HTML formatting is simplified.\n      No endorsement by the State of Queensland or QAO is implied.</p>\n\n      <h2 id=\"about-people\">People</h2>\n      <p>1,557 names appear as speakers in the corpus since 1993; 313 of them currently sit in a\n      state or federal parliament. 829 portrait photographs cover just over a thousand of those\n      names: 551 official portraits from Parliament House, fetched through OpenAustralia because\n      the official image API blocks every identified research tool, reproduced under aph.gov.au's\n      site-wide CC BY-NC-ND 4.0 terms; and 277 from Wikimedia Commons for state parliamentarians\n      and pre-2006 federal members, each individually licensed — Creative Commons, public domain\n      or CC0 — and credited by name on the person page it appears on.</p>\n      <p>Declared shareholdings, real estate, directorships, gifts, travel and liabilities are\n      shown for 317 sitting members — every House member (151), all but one senator (73) and every\n      Queensland MP (93) — 10,052 declared entries in total, each one linking to the exact page of\n      the source PDF it was read from. They are not in OPAX's ask-and-search index: the House and\n      Senate registers are licensed CC BY-NC-ND, Queensland's terms could not even be read (they\n      sit behind a firewall that blocked every request), and a rewritten version of a declared\n      interest would be a derivative work in a way a fact with a link back to the original PDF is\n      not.</p>\n\n      <h2 id=\"about-machines\">Enrichments written by machines</h2>\n      <ul class=\"about-list\">\n        <li><strong>Topic labels</strong>: every speech is, eventually, tagged against a fixed\n        taxonomy of 21 subjects — gambling, financial services, mining &amp; energy, climate &amp;\n        environment, property &amp; construction, housing, health, media &amp; communications,\n        hospitality &amp; alcohol, defence &amp; security, agriculture, unions &amp; the workplace,\n        immigration, First Nations affairs, tax &amp; the budget, education, welfare &amp; social\n        services, integrity &amp; democracy, infrastructure &amp; transport, justice &amp; law, and\n        foreign affairs — applied by a mix of the hosting platform's own labeller and separate\n        agents that read back over what it produced. The pass is still running: a speech with no\n        topic chip yet has simply not been reached, not been checked and found to have none.</li>\n        <li><strong>Machine briefs</strong>: many speeches and every topic page carry a short \"In\n        brief\" summary, written by a language model from that one passage alone and labelled as a\n        machine summary. It is a reading aid, not a replacement for the speech underneath it.</li>\n        <li><strong>Report essays</strong>: the six standing reports retrieve live from the corpus\n        for every section, and every factual claim is built to trace back to a real, quoted\n        passage — but the connecting prose (the opening summary, the era-by-era narrative) is a\n        model's synthesis of the report's own generated sections, written last. Read it as a guide\n        to where to look, not as the finding.</li>\n        <li><strong>Bill summaries</strong>: 1,698 federal bills carry a three-sentence,\n        plain-English account of what their explanatory memorandum or Bills Digest says, written\n        by a model and checked by a mechanical rule that rejects any sentence copying nine or more\n        consecutive words from the source. Every one carries its own attribution, because an\n        explanatory memorandum is a bill's own sponsor explaining their own bill, not a neutral\n        account of what it will do.</li>\n        <li><strong>Explain flow</strong>: the \"Explain this money\" walkthrough on a donor or party\n        page is not a language model at all — its sentences are assembled by ordinary code from the\n        same structured donation and grant figures the map itself draws on. It can still be wrong,\n        but only the way a mail-merge can be wrong: a bad number or a mis-filed category upstream,\n        never an invented claim.</li>\n      </ul>\n\n      <h2 id=\"about-limits\">What this cannot prove</h2>\n      <p>OPAX puts the record and the money side by side. It does not draw a conclusion from\n      them, and neither should a reader without checking the primary source first.</p>\n      <ul class=\"about-list\">\n        <li>Money near a decision is a pattern to investigate, not evidence of a favour.</li>\n        <li>A division is not the whole vote: most questions in every chamber are decided on the\n        voices, so a member with no recorded division on a bill did not necessarily do nothing.</li>\n        <li>Every donation, meeting and grant figure here is a floor. Amounts under a\n        jurisdiction's reporting threshold, and anything from a jurisdiction OPAX does not cover,\n        are invisible by construction, not because nothing happened.</li>\n        <li>Registration under the Foreign Influence Transparency Scheme, or an entry in a\n        lobbyist register, is a legal disclosure the law requires, not a finding of wrongdoing.</li>\n        <li>A donor receiving a grant, or a bill's sponsor sharing an industry with donors to their\n        party, is a fact on the public record. What it means is for the reader to weigh, with the\n        primary sources OPAX links to at every step.</li>\n      </ul>\n      <p class=\"fineprint\">The corpus's own technical limits — what Hansard is and is not, where\n      coverage is thin, which members' records are unreliable — are on the\n      <a href=\"/methods\">methods page</a>, not repeated here.</p>\n\n      <h2 id=\"about-who\">Who makes it</h2>\n      <p>OPAX is a side project of Jake Tracey, of <a href=\"https://noice.net.au\"\n      rel=\"noopener\">Noice</a>. It is independent and non-partisan, built outside working hours,\n      and the data it carries belongs to the public bodies that published it. Three things make\n      it possible.</p>\n      <ul class=\"about-list\">\n        <li><strong>Noice</strong> (<a href=\"https://noice.net.au\" rel=\"noopener\">noice.net.au</a>)\n        is a Melbourne digital agency for the AI era, building digital experiences and AI\n        automation for government and large organisations. The craft OPAX runs on, from how a\n        page is built to how a model is kept honest, was learned there, and the tooling comes\n        with it.</li>\n        <li><strong>Progress Agentic RAG</strong> (<a\n        href=\"https://www.progress.com/agentic-rag?utm_source=opax&amp;utm_medium=referral&amp;utm_campaign=about\"\n        rel=\"noopener\">progress.com/agentic-rag</a>) holds the corpus. Every speech, bill,\n        division and statement is indexed in a knowledge box on the platform, which does the\n        retrieval, the reranking and the citation binding behind every answer on the Ask page.\n        OPAX writes the prompts and checks the answers; the platform finds the passages.</li>\n        <li><strong>CorpusKit</strong> (<a href=\"https://corpuskit.org?utm_source=opax&amp;utm_medium=referral&amp;utm_campaign=about\"\n        rel=\"noopener\">corpuskit.org</a>) is the open source research portal that grew alongside\n        OPAX: point it at an empty knowledge box and it reads the corpus, designs the taxonomy\n        and the knowledge graph around it, writes the questions worth asking and opens as a\n        branded portal. Much of what works here was built there first, and the parts that\n        generalise flow back to it. It is Apache 2.0, and any organisation with a body of\n        research can use it.</li>\n      </ul>\n      <p>If OPAX helps you find a blind spot, that is the point. If you find one in OPAX itself,\n      a missing source, a wrong number, a jurisdiction not yet covered, the fastest fix is an\n      issue on GitHub, below.</p>\n\n      <h2 id=\"about-licences\">Licences and reuse</h2>\n      <p>Source: <a href=\"https://www.legislation.gov.au/\">Federal Register of Legislation\n      (legislation.gov.au)</a>, <a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>.\n      Instrument metadata is arranged into a catalogue with titles verbatim and\n      one API-returned version per title, which may be historical. Current/latest flags are retained\n      verbatim. OPAX shows metadata only. Each export carries FRL's dated attribution.\n      The Commonwealth Coat of Arms and content marked as third party are exceptions. See the\n      <a href=\"https://www.legislation.gov.au/terms-of-use\">FRL terms of use</a>; no endorsement is implied.</p>\n      <p>OPAX's own code is open source under AGPL-3.0, at\n      <a href=\"https://github.com/jaketracey/opax\" rel=\"noopener\">github.com/jaketracey/opax</a>.\n      The data behind it is not ours, and it carries a patchwork of licences rather than one. The\n      Hansard record itself — however it reaches OPAX, through TheyVoteForYou, OpenAustralia or a\n      state Hansard feed — is Commonwealth or state parliamentary copyright, reproduced here under\n      CC BY-NC-ND terms (ACT Hansard is © ACT Legislative Assembly, used under CC BY-NC-ND 4.0\n      with attribution to the Assembly; its official portraits are excluded from that licence and\n      are not used here); TheyVoteForYou's own compiled division data carries a separate open\n      licence of its own (the Open Data Commons Open Database Licence). Most of the money data —\n      AEC returns, GrantConnect and the Queensland grants portal, the Queensland and Tasmanian\n      donation registers, the Foreign Influence Transparency Scheme register, and most lobbyist\n      registers — is Creative Commons Attribution, in one version or another. The House and Senate\n      registers of members' interests are licensed CC BY-NC-ND, which is why they appear on OPAX\n      as facts with a link to the source page rather than as reproduced text; Queensland's register\n      carries no verified licence at all, so it is treated the same cautious way. And a few sources\n      — Western Australian, ACT and Northern Territory donations among them — are held under\n      all-rights-reserved terms and are kept off the public site entirely; that data exists only\n      for internal research. Every page that carries licensed data names its source and, where one\n      applies, its licence; when the two disagree, trust the page, since licences and coverage\n      windows both move and this paragraph will not always be the first place they are updated.</p>\n\n      <h2 id=\"about-contact\">How to reach us</h2>\n      <p>OPAX has no dedicated inbox. Data errors are the corrections we most want to hear about,\n      and the fastest way to report one, ask about the methodology, or point out a source we have\n      missed is to open an issue on\n      <a href=\"https://github.com/jaketracey/opax\" rel=\"noopener\">the GitHub repository</a>, where\n      the code, the ingestion scripts and the issue tracker all live in one place.</p>\n      </div>\n    </section>\n\n    <!-- ============================ METHODS ============================ -->\n    <section id=\"panel-methods\" class=\"panel\" hidden aria-label=\"Methods\">\n      <p class=\"kicker\">Methods</p>\n      <h2>How OPAX works, and how to cite it</h2>\n      <p>Federal legislative instruments are a separate metadata catalogue.\n      Cite the FRL id and the authoritative version linked on its detail page. Source: Federal\n      Register of Legislation (legislation.gov.au), <a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>.\n      OPAX shows metadata only; version start, registration and commencement are distinct dates.</p>\n      <p><a href=\"/audit\">Queensland audit reports</a> carries the report index and QAO's\n      numbered recommendations published as HTML. Cite the report number and year, the\n      labelled tabled date, and its authoritative QAO link. Source: Queensland Audit Office,\n      <a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>, unless otherwise noted.\n      © The State of Queensland (Queensland Audit Office) 2026. Copyright exceptions are recorded\n      per report and their bodies withheld. PDF bodies, entity responses and the app are phase 2.</p>\n\n      <h3>What OPAX is, and is not</h3>\n      <p>OPAX is a retrieval and analysis layer over public records. It is not the official\n      record. Before publishing a quote, verify the wording at the source link on the document\n      page. Every document links to its official origin where one exists.</p>\n\n      <h3>Corpus construction</h3>\n      <p>Speeches are included from <strong>13 March 1993</strong>, the election that seated the\n      longest-serving current federal parliamentarian, so nothing in the corpus predates a\n      currently serving member. Speeches under 200 characters are excluded (procedural fragments),\n      duplicates across overlapping sources are removed, and procedural noise (division\n      roll-calls, chair interjections, day indexes) is stripped. The machine-readable corpus\n      manifest, including per-source counts and the current corpus version, is at\n      <a href=\"/corpus.json\">corpus.json</a>.</p>\n\n      <h3>Retrieval and generation</h3>\n      <p>Search runs hybrid semantic + keyword retrieval with a reranking pass. Answers are\n      generated only from retrieved passages, with citations. Embeddings:\n      <code>multilingual-2024-05-06</code>. Generation model (pinned):\n      <code>gemini-2.5-flash-lite</code>. Model identity may change between corpus versions and\n      is recorded in the manifest.</p>\n\n      <h3>Reproducibility</h3>\n      <p>Searches are reproducible given a query, filters and corpus version: every export file\n      embeds all three. Generated answers are <strong>not</strong> reproducible and must not be\n      quoted as data. The supported method for a paper: state the question, cite the returned\n      documents by their permanent OPAX links, and archive the export file.</p>\n\n      <h3>Known limitations</h3>\n      <ul class=\"about-list\" id=\"methods-defects\"><!-- filled from corpus.json --></ul>\n      <ul class=\"about-list\">\n        <li>Hansard is a revised record (\"substantially verbatim\"), not a raw transcript.</li>\n        <li>Party labels use a 15-value canonical vocabulary; some speeches carry no party label.</li>\n        <li>State coverage windows differ by parliament (QLD only from 2024, NSW/VIC from 2015).</li>\n      </ul>\n\n      <h3>Corrections</h3>\n      <ul class=\"about-list\">\n        <li><strong>30 September 2026, grants by seat.</strong> Grant program pages now take each\n        seat's member and party on the grant date from the parliamentary service records, which date\n        every change of party. They previously used the member's current party, so a member who later\n        changed party was counted under the later party. A seat that was vacant on the grant date is\n        now left out of the \"to seats held by the government of the day\" share, as awards without an\n        electorate already were, and shown as a vacant seat. That share changed for 50 federal\n        programs; award totals did not change.</li>\n      </ul>\n\n      <h3>Licence, code and corrections</h3>\n      <p>AGPL-3.0. Source and issue tracker:\n      <a href=\"https://github.com/jaketracey/opax\" rel=\"noopener\">github.com/jaketracey/opax</a>.\n      Data errors are corrections we want, so please report them.</p>\n    </section>\n\n    <!-- ====================== EXPENSE CATEGORIES ======================= -->\n    <section id=\"panel-expenses\" class=\"panel\" hidden aria-label=\"Expense categories\">\n      <p class=\"kicker\">Parliamentary expenses</p>\n      <h2>What the expense categories mean</h2>\n      <p class=\"lede\">Every parliamentarian page on OPAX splits claimed expenses by category. Those\n      category names are the Independent Parliamentary Expenses Authority's own, reproduced\n      unchanged from its quarterly expenditure reports, so a figure here can be checked line by\n      line against the published source. This page says what each one covers.</p>\n      <p class=\"fineprint\">Some of these are not expense types at all. IPEA records the purpose of\n      a trip against transport lines, so labels such as parliamentary duties or electorate duties\n      answer why the travel happened, not what was bought. Others are entitlements paid at a set\n      rate rather than reimbursements of receipts. Both are marked below.</p>\n      <div id=\"expenses-defs\"><p class=\"status\">Loading definitions…</p></div>\n    </section>\n\n    <!-- ============================ PRIVACY ============================ -->\n    <!-- Every claim here is checked against the code and docs listed in\n         docs/PRIVACY.md. Facts and decisions the repository cannot settle\n         are marked placeholders; scripts/check_privacy_placeholders.mjs fails\n         `npm run check` and the deploy scripts while any remain. -->\n    <section id=\"panel-privacy\" class=\"panel\" hidden aria-labelledby=\"privacy-title\">\n      <p class=\"kicker\">Privacy</p>\n      <h1 id=\"privacy-title\">What OPAX collects and who receives it</h1>\n      <p class=\"lede\">The Open Parliamentary Accountability Exchange (OPAX) publishes the public\n      record of Australian politics. Reading it needs no account. This page sets out what the OPAX\n      website and iPhone app collect when you use them, which other companies receive it, how long\n      it is kept and how to have it deleted.</p>\n      <p class=\"fineprint\">Last updated 6 October 2026. This page covers the OPAX website and the\n      OPAX app for iPhone, which is in testing.</p>\n\n      <h2 id=\"privacy-summary\">In short</h2>\n      <ul class=\"about-list\">\n        <li>Reading the record needs no account, on the website or in the app.</li>\n        <li>Every request reaches OPAX's servers with your IP address, which is used to limit\n        request rates and refuse abusive traffic.</li>\n        <li>The website counts visits with Google Analytics and PostHog. They receive your IP\n        address and details of your browser, but never the words you type or the answers you get.\n        The app has no analytics.</li>\n        <li>Questions, searches of the record's documents and search summaries go to the services\n        that search the record and write answers. OPAX adds no account details to them.</li>\n        <li>An account holds your email address and whatever you choose to write or save. Your\n        email address is never shown to other members.</li>\n        <li>Voice is optional. Your voice goes to ElevenLabs, a third-party AI provider, only\n        during a call you start.</li>\n        <li>You can delete your account, and what you wrote, at any time.</li>\n        <li>OPAX shows no advertising and does not sell personal information.</li>\n      </ul>\n\n      <nav class=\"privacy-contents\" aria-labelledby=\"privacy-contents-title\">\n        <p class=\"kicker\" id=\"privacy-contents-title\">On this page</p>\n        <ul>\n          <li><a href=\"#privacy-reading\">Reading the record</a></li>\n          <li><a href=\"#privacy-accounts\">Community accounts</a></li>\n          <li><a href=\"#voice\">Talking to OPAX by voice</a></li>\n          <li><a href=\"#privacy-deletion\">Deleting your account</a></li>\n          <li><a href=\"#privacy-providers\">Who else receives data</a></li>\n          <li><a href=\"#privacy-children\">Children</a></li>\n          <li><a href=\"#privacy-contact\">Questions and requests</a></li>\n          <li><a href=\"#privacy-changes\">Changes to this page</a></li>\n        </ul>\n      </nav>\n\n      <h2 id=\"privacy-reading\">Reading the record</h2>\n      <h3>On the website</h3>\n      <p>You can read, search and ask without an account. OPAX runs on Cloudflare, so every\n      request your browser makes reaches Cloudflare's network with your IP address, as a request\n      to any website does.</p>\n      <p>OPAX uses the address to limit how often one address can ask questions (20 a minute),\n      ask for suggested follow-up questions and search summaries (20 a minute), search (120 a\n      minute) and draw share images (60 a minute). Cloudflare counts these per address over\n      60-second windows. OPAX also refuses some requests from networks that run automated\n      scraping.</p>\n      <p>Sign-in, account and voice requests have limits of their own. For these, OPAX stores a\n      counter under a SHA-256 hash of the address and the time window, not under the address\n      itself. Expired counters are deleted during later sign-in requests, a day or more after\n      their window ends.</p>\n      <p>Requests that OPAX's server handles are logged in Cloudflare Workers Logs. They\n      include page loads, searches, questions, other requests for data the server works out, and\n      analytics events passed on to PostHog. Each log entry records the address requested,\n      which for a search includes the search words. Files the site serves as they are, such as\n      scripts, styles and most published data files, come straight from Cloudflare's network\n      without reaching the server, so they are not in these logs. On OPAX's Cloudflare plan the\n      logs are kept for 7 days, as\n      <a href=\"https://developers.cloudflare.com/workers/observability/logs/workers-logs/\" rel=\"noopener\">Cloudflare\n      documents</a>, and then deleted. Cloudflare may record connection details, such as your IP\n      address, with each entry.</p>\n      <p>Cloudflare's own traffic and security analytics for opax.com.au also record requests\n      with their IP addresses. Cloudflare\n      <a href=\"https://developers.cloudflare.com/analytics/graphql-api/limits/\" rel=\"noopener\">documents</a>\n      that it keeps these request-level records for 31 days.</p>\n\n      <h3 id=\"privacy-questions\">Questions and searches</h3>\n      <p>Where the words you type go depends on what you are doing.</p>\n      <ul class=\"about-list\">\n        <li><strong>Searches of OPAX's catalogs</strong>, such as people, parties, donors,\n        contracts, grants, declared interests, pay and expenses, are looked up on OPAX's own\n        server. The search words go to no other service.</li>\n        <li><strong>Searches of the record's documents</strong>, including the standard search\n        of everything and searches of bill text, also send the search words and filters to\n        Progress Agentic RAG, the service that holds the record and finds the passages that\n        match.</li>\n        <li><strong>Search summaries.</strong> Unless you have turned summaries off, a search for\n        words also asks for a short summary of the records it found, even when it searched only\n        the catalogs. The search words, filters and those records go through Progress to a\n        language model reached through OpenRouter.</li>\n        <li><strong>Questions</strong> on the Ask page and in a conversation go to Progress, which\n        finds passages, then with those passages to the language model through OpenRouter.\n        Follow-up questions carry the conversation's earlier turns with them.</li>\n      </ul>\n      <p>Searches made by the voice assistant and by research tools follow the same paths. OPAX's\n      code adds no account details or other identifier to these requests. Progress can still\n      receive your IP address with them: Cloudflare, which runs OPAX's server, documents that it\n      adds the visitor's IP address to requests the server makes to services outside Cloudflare,\n      and Progress is outside it. OpenRouter is called by Progress, not by OPAX's server.</p>\n      <p>What these services keep, and for how long, is set by their own terms:\n      <a href=\"https://www.progress.com/legal/privacy-policy\" rel=\"noopener\">Progress's privacy\n      policy</a>, <a href=\"https://openrouter.ai/privacy\" rel=\"noopener\">OpenRouter's privacy\n      policy</a>, and the policy of the provider OpenRouter sends the request to.</p>\n      <p>So that a repeated question needs no new work, Cloudflare keeps copies of answers to\n      opening questions, search results and summaries for between ten minutes and seven days.\n      The copies are filed by the question, not by who asked it.</p>\n\n      <h3>Stored in your browser</h3>\n      <p>The website keeps a few things in your browser, and they last for different times.</p>\n      <ul class=\"about-list\">\n        <li><strong>Two preferences</strong> stay until you clear this site's data: the kind of\n        question you last chose in the question builder, and that you turned search summaries\n        off. Turning summaries back on removes the second.</li>\n        <li><strong>Two things last only as long as the open tab</strong>: how you were reading a\n        search, and the question and answer you carry from Ask into a conversation. That\n        question and answer is removed as soon as the conversation opens.</li>\n        <li><strong>Your most recent conversations with OPAX</strong>, up to 20, so that you can\n        return to them. Older ones drop off as new ones arrive, sooner if they take up too much\n        space. You can delete a conversation from the conversation list; while you are signed\n        in, that deletes the copy in your account too. If you sign in on the website,\n        conversations are copied to your account, including ones saved before you signed in;\n        see <a href=\"#privacy-accounts\">Community accounts</a>.</li>\n      </ul>\n      <p>Clearing this site's data in your browser removes what the browser holds, but not the\n      copies in your account. The analytics cookies are described next.</p>\n\n      <h3 id=\"privacy-analytics\">Analytics on the website</h3>\n      <p>The website uses Google Analytics, loaded through Google Tag Manager, and PostHog to\n      count visits and see which features are used. Both receive the page's address with any\n      search terms and fragments removed, and a fixed list of events: a question or search\n      started, finished or failed, with its duration and result counts; a source opened; a\n      download; a link followed to another site; and similar actions. They never receive\n      question text, search words, answers, page titles, postcodes or error messages. Campaign\n      tags in a link are kept only as a plain source, medium and campaign name; other tags and\n      advertising click identifiers are dropped.</p>\n      <p>With each event, both services also receive details your browser shares, such as your\n      browser and its version, operating system, device type, screen and window size, language\n      and time zone. PostHog also receives the domain of the site that linked you to OPAX, but\n      not the rest of its address.</p>\n      <p>Each service stores an anonymous identifier in your browser so that a returning browser\n      and a visit can be counted. Google Analytics sets cookies whose names begin with\n      <code>_ga</code>, which Google documents as lasting two years. PostHog keeps its identifier\n      in a cookie that lasts a year and in local storage, which stays until you clear it.\n      Neither builds a profile of you: PostHog's person profiles, session recording and surveys\n      are off, and Google signals and advertising personalisation are off.</p>\n      <p>PostHog's cookie also records the full address you first arrived at, including any\n      search words in it. Like every cookie for opax.com.au, it travels with your requests to\n      OPAX's server, which does not use it and does not pass it on. OPAX removes that address\n      from the events PostHog receives.</p>\n      <p>Your browser sends Google Analytics events straight to Google, so Google receives your\n      IP address. PostHog events pass through OPAX's server, which forwards your IP address to\n      PostHog's ingestion service in the United States, so that PostHog places visits by your\n      location rather than by the server's. PostHog may store the address with the event.</p>\n      <p>Both services keep the events they receive for the retention period of OPAX's account\n      with them, under their own terms:\n      <a href=\"https://policies.google.com/privacy\" rel=\"noopener\">Google's privacy policy</a>\n      and <a href=\"https://posthog.com/privacy\" rel=\"noopener\">PostHog's privacy\n      policy</a>.</p>\n      <p>If your browser sends a Do Not Track signal, neither service receives anything, though\n      PostHog may still store its identifier in your browser. Analytics run only on opax.com.au,\n      and community pages load none at all.</p>\n      <p>The grants map loads its map tiles from OpenStreetMap's servers, which receive your IP\n      address.</p>\n\n      <h3>In the iPhone app</h3>\n      <p>The OPAX iPhone app is in testing. It needs no account to read. It has no analytics, no\n      advertising and no tracking, and sends no device identifier. The seat you choose and the\n      records it keeps for offline reading stay on your phone. Its searches look up OPAX's own\n      catalogs of people, declared interests, pay and expenses on OPAX's server, and are not\n      sent to Progress or to a language model. Its requests reach OPAX's servers with your\n      phone's IP address, under the same limits and logs as the website. Pages the app opens on\n      opax.com.au are the website, and the website sections above apply to them.</p>\n      <p>If you use the app's Use my location option when picking your electorate, iOS asks for\n      your permission, and the app then uses one reading of your location, on your iPhone, to\n      suggest an electorate. Your location is never sent to OPAX or anyone else, and is not stored: the\n      app downloads every electorate's outline before it reads your location, so its requests\n      are the same wherever you are, and only the electorate you confirm is saved. The app never\n      asks for your location in the background.</p>\n\n      <h2 id=\"privacy-accounts\">Community accounts</h2>\n      <p>An account is optional. On the website it lets you keep reading lists, take part in\n      discussions, message other members and connect research tools. If you sign in to the\n      iPhone app, it is the same account, and there it is needed only to talk to OPAX by\n      voice.</p>\n      <h3>What an account holds</h3>\n      <ul class=\"about-list\">\n        <li><strong>Your email address</strong>, to sign you in and send the emails described\n        below. It is never shown on your profile or to other members.</li>\n        <li><strong>Your display name and a short bio</strong>, if you add them, the date you\n        joined and your follower count. These are public.</li>\n        <li><strong>What you write and save</strong>: discussions and replies, which are public;\n        reading lists, which are private until you share them; saved discussions, which only you\n        see; follows, likes and blocks; and messages to other members.</li>\n        <li><strong>Saved conversations with OPAX.</strong> While you are signed in on the\n        website, your conversations are copied to your account so that they appear on your other\n        devices, including any that browser saved before you signed in. An account holds up to\n        50. Only you can see them.</li>\n        <li><strong>Your settings</strong>: who can message you, and whether you receive reply\n        emails.</li>\n      </ul>\n      <p>Direct messages are visible only to their two participants. OPAX stores them; they are\n      not end-to-end encrypted. If you report a message, moderators can read that message and\n      your reason. Likes, replies and follows can notify the member they concern. Blocking a\n      member stops their messages, removes follows between you and hides each other's\n      discussions while you are signed in.</p>\n\n      <h3>Signing in</h3>\n      <p>OPAX emails you a sign-in link and, when you sign in from the app, an eight-digit code\n      as well. Each expires after\n      15 minutes and works once. OPAX stores only a hash of the link and a keyed hash of the\n      code, with your email address, and deletes them a day or more after they expire, during\n      later sign-in requests.</p>\n      <p>Signing in starts a session that lasts up to 30 days. On the website it is held in a\n      secure cookie that page scripts cannot read; if you sign in to the app, it is held in the\n      iPhone's Keychain, on that device only. OPAX stores a hash of the session token, the account it\n      belongs to, when it started and ends, and whether it began on the website or in the app.\n      It does not store your IP address or device details with a session. You can sign out on\n      one device or on every device.</p>\n\n      <h3>Email</h3>\n      <p>Emails come from login.opax.com.au and are sent through Cloudflare's email service.\n      OPAX sends sign-in emails, account deletion codes and, when someone replies to a\n      discussion you started, a reply notification. You can turn reply emails off in Privacy\n      &amp; messages, and each one has an unsubscribe link. OPAX sends no newsletters or\n      marketing email. Cloudflare's email service keeps its own delivery records, under\n      <a href=\"https://www.cloudflare.com/privacypolicy/\" rel=\"noopener\">Cloudflare's privacy policy</a>.</p>\n\n      <h3>Research tools</h3>\n      <p>Members can create keys that let research tools search the record through OPAX's MCP\n      service. Keys are stored as hashes, expire after 90 days, can be revoked at any time and\n      record when they were last used. Searches made with a key go through the same search as\n      the website.</p>\n\n      <h2 id=\"voice\">Talking to OPAX by voice</h2>\n      <p>Talk to OPAX is an optional voice assistant for signed-in members. It answers from the\n      same public record and links its sources. It is run by ElevenLabs, a third-party AI\n      provider.</p>\n      <h3>Your microphone</h3>\n      <p>OPAX uses your microphone only during a call you start. On the website, opening the\n      voice panel does not touch the microphone: it starts when you choose Start talking, and\n      stops when the call ends, when you close the panel and when you leave the tab. If you use\n      voice in the app, you agree to the terms in this section once, then iOS asks for microphone\n      permission the first time you start a call. Your agreement is stored on your iPhone; you can withdraw it\n      at any time on the voice screen, and the app asks again before your next call. A call ends\n      when you leave the app.</p>\n      <h3>What is sent, and to whom</h3>\n      <p>During a call, your voice streams through OPAX's server to ElevenLabs. ElevenLabs turns\n      your speech into text, writes the replies with a language model that ElevenLabs runs for\n      the assistant, and speaks them back. Anything you type during a call goes the same way. OPAX gives ElevenLabs a\n      random identifier for the call and the call's time limit; its code does not give\n      ElevenLabs your email address or account details. ElevenLabs can receive your IP address\n      with the connection, because Cloudflare adds the visitor's IP address to requests that\n      OPAX's server makes to services outside Cloudflare. When the assistant looks something up,\n      its search runs through OPAX's own search, as described under\n      <a href=\"#privacy-questions\">Questions and searches</a>.</p>\n      <h3>What is kept</h3>\n      <p>When OPAX last checked (9 September 2026), its voice assistant was set at ElevenLabs\n      not to record audio and to delete transcripts after one day. ElevenLabs' own\n      <a href=\"https://elevenlabs.io/privacy-policy\" rel=\"noopener\">privacy policy</a> also applies. OPAX itself keeps no recording and no transcript. The transcript\n      you see during a call is not saved in your browser or in the app, and is never sent to\n      analytics.</p>\n      <p>For each call, OPAX keeps a record linked to your account: its state, the seconds\n      reserved and charged, when it started and ended, and ElevenLabs' reference for the\n      conversation.</p>\n      <h3 id=\"voice-allowance\">Your 10 minutes</h3>\n      <p>Each account has 10 minutes (600 seconds) of voice in total, not each month. All\n      members also share a monthly budget of 40,000 seconds, and no more than two calls can run\n      at once. The call records above are how OPAX counts all three.</p>\n      <p>Starting a call reserves your remaining time, or what is left of the month's budget if\n      that is less. Cancelling the reservation before OPAX starts connecting the call returns\n      the time, and a reservation that is never used expires without charge. Once OPAX starts\n      connecting the call, the time can stay charged if OPAX cannot confirm that no call ran or\n      how it ended, for example when the connection to ElevenLabs fails partway or drops. A call\n      that ends normally is charged for the seconds it ran. A few accounts approved by OPAX can\n      make repeated calls of up to 10 minutes each.</p>\n\n      <h2 id=\"privacy-deletion\">Deleting your account</h2>\n      <p>On the website, open <a href=\"/community?view=delete-account\">Delete your account</a>\n      from your account page. If you have signed in to the iPhone app, Delete account under\n      Account does the same. OPAX emails you a\n      fresh code, and entering it removes the account from OPAX's live database at once.\n      Deletion cannot be undone. Anyone who can receive the account's email can do it, since\n      both signing in and the deletion code go to that address.</p>\n      <h3>What is deleted</h3>\n      <ul class=\"about-list\">\n        <li>Your email address, display name, bio and settings, and any voice access OPAX gave\n        your account.</li>\n        <li>Every session on every device, any unused sign-in links and codes, and your research\n        tool keys.</li>\n        <li>Everything you wrote or saved: discussions, replies, reading lists, saved\n        conversations, messages you sent, likes, bookmarks, follows, blocks, reports you made,\n        and notifications to or from you.</li>\n        <li>Emails waiting to be sent to you, your unsubscribe links and the rate-limit counters\n        tied to your account.</li>\n      </ul>\n      <h3>What is kept, and why</h3>\n      <ul class=\"about-list\">\n        <li><strong>Voice call records</strong> lose their link to your account but keep their\n        seconds and times, because the shared monthly budget and the two-call limit depend on\n        them; deleting them would hand back time already used. Each keeps ElevenLabs' reference\n        for its conversation until OPAX's housekeeping, which runs every five minutes, clears it\n        one day after the call was recorded as ended. Clearing the reference does not delete\n        ElevenLabs' copy of the conversation, which follows the ElevenLabs settings above.</li>\n        <li><strong>Other members' replies</strong> to a discussion you started stay, under a\n        placeholder titled \"Deleted discussion\" with no text, link or date. A conversation you\n        were part of stays readable by the other member, with their own messages only, and\n        takes no new messages. You are shown as \"Deleted account\". What other members wrote is\n        not changed, even where it quotes you.</li>\n        <li><strong>Rate-limit counters</strong> for IP addresses stay until they expire.</li>\n        <li><strong>Emails already sent</strong> cannot be recalled.</li>\n        <li><strong>Recovery history.</strong> Cloudflare keeps a rolling history of OPAX's\n        database so that it can be restored to an earlier point if something goes wrong. It is\n        always on, and on OPAX's plan it covers the last 30 days, as\n        <a href=\"https://developers.cloudflare.com/d1/reference/time-travel/\" rel=\"noopener\">Cloudflare\n        documents</a>. Your deleted data stays in it for up to 30 days, then is gone. OPAX runs\n        no other scheduled backup or export of the database.</li>\n      </ul>\n      <p>After deletion, OPAX's live database keeps no record of your email address. Signing up\n      again with it creates a new account, with a fresh 10 minutes of voice. The browser you delete from\n      clears its saved conversations; other browsers keep their copies until you clear this\n      site's data there. The public record is not affected.</p>\n\n      <h2 id=\"privacy-providers\">Who else receives data</h2>\n      <ul class=\"about-list\">\n        <li><strong>Cloudflare</strong> runs OPAX's servers, database, logs, rate limits and\n        email, and handles every request with your IP address. OPAX's community database is held\n        in Cloudflare's Oceania region.</li>\n        <li><strong>Progress Agentic RAG</strong> receives questions, searches of the record's\n        documents and the inputs to search summaries, as set out under\n        <a href=\"#privacy-questions\">Questions and searches</a>, including those made by the\n        voice assistant and by research tools. It can receive your IP address with them. OPAX's\n        knowledge box is in its AWS Sydney zone.</li>\n        <li><strong>OpenRouter</strong>, and the model provider it routes to, receives from\n        Progress the questions, search words and passages needed to write answers and\n        summaries.</li>\n        <li><strong>ElevenLabs</strong> receives voice audio, messages typed during a call and\n        the call's random identifier, and can receive your IP address with the connection. The\n        language model ElevenLabs runs for the assistant receives the words of the conversation\n        through ElevenLabs. OPAX uses ElevenLabs' standard service, not one of its regional data\n        residency services, and ElevenLabs\n        <a href=\"https://elevenlabs.io/docs/overview/administration/data-residency\" rel=\"noopener\">states</a>\n        that it stores this data in the United States, while processing can also happen\n        elsewhere, through its affiliates and subprocessors. Its\n        <a href=\"https://elevenlabs.io/privacy-policy\" rel=\"noopener\">privacy policy</a>\n        applies.</li>\n        <li><strong>Google</strong>, through Analytics and Tag Manager, receives page addresses,\n        the events and browser details listed above and your IP address, on the website\n        only.</li>\n        <li><strong>PostHog</strong> receives the same events and browser details, and your IP\n        address forwarded by OPAX's server, on the website only, in the United States.</li>\n        <li><strong>OpenStreetMap</strong> receives your IP address when the grants map loads its\n        tiles.</li>\n      </ul>\n\n      <h2 id=\"privacy-children\">Children</h2>\n      <p>Reading OPAX needs no account at any age. Community accounts and voice are for people\n      aged 16 and over. OPAX does not ask for a date of birth or check anyone's age. Anyone who\n      can receive an account's email can sign in to it and delete it at any time.</p>\n\n      <h2 id=\"privacy-contact\">Questions and requests</h2>\n      <p>OPAX is run by Jake Tracey, as an independent side project, and he is responsible for\n      this policy.</p>\n      <p>OPAX does not yet have a private contact address. One is coming, and this page will name\n      it. Until then:</p>\n      <ul class=\"about-list\">\n        <li>to delete your account and everything it holds, sign in and use Delete your account\n        on the website (or, if you have signed in to the iPhone app, Delete account there); it\n        asks for a fresh code sent to your email address;</li>\n        <li>to see or change what your account holds, sign in: you can change your profile and\n        settings, and delete your reading lists, discussions, replies and saved\n        conversations;</li>\n        <li>for anything that is not private, such as a question about this page or an error in\n        the record, open an issue on <a href=\"https://github.com/jaketracey/opax/issues\" rel=\"noopener\">GitHub</a>.\n        Issues there are public, so leave personal details out of them.</li>\n      </ul>\n      <p>More help is on the <a href=\"/support\">support page</a>.</p>\n\n      <h2 id=\"privacy-changes\">Changes to this page</h2>\n      <p>When this page changes, the date at the top changes with it. The page is part of OPAX's\n      public source code, so every earlier version, and what changed, is in the history of\n      <a href=\"https://github.com/jaketracey/opax\" rel=\"noopener\">github.com/jaketracey/opax</a>.</p>\n    </section>\n    <!-- ============================ SUPPORT ============================ -->\n    <!-- /support?record=<path> names a record by its title, and pre-fills the\n         GitHub issue, only when the path is exactly a published record's page\n         (renderSupport in app.js, public/record-paths.js). -->\n    <section id=\"panel-support\" class=\"panel\" hidden aria-labelledby=\"support-title\">\n      <p class=\"kicker\">Support</p>\n      <h1 id=\"support-title\">Help with OPAX</h1>\n      <p class=\"lede\">The Open Parliamentary Accountability Exchange brings together Australian\n      parliamentary speeches, votes, political funding and public disclosures. Search across the\n      records, trace connections and follow claims back to their original sources.</p>\n      <p>OPAX is independent and non-partisan. It is not a government service and is not\n      affiliated with any parliament, government or political party.\n      <a href=\"/about\">More about OPAX</a>.</p>\n\n      <h2 id=\"support-report\">Report a wrong record or a wrong answer</h2>\n      <p id=\"support-record\" hidden>You are reporting\n      <a id=\"support-record-link\" href=\"/\">this record</a>.</p>\n      <p>OPAX copies its records from public sources, and its answers, summaries and voice replies\n      are written by language models from those records, so either can be wrong. To report a\n      mistake, open an issue on GitHub with:</p>\n      <ul class=\"about-list\">\n        <li>the link to the record or page, or, for an answer, the question you asked and the\n        words that are wrong;</li>\n        <li>what is wrong;</li>\n        <li>the source that shows it, if you have one.</li>\n      </ul>\n      <p><a class=\"ui-button\" id=\"support-issue-link\" href=\"https://github.com/jaketracey/opax/issues/new?title=Correction\" rel=\"noopener\">Report it on GitHub</a></p>\n      <p>Corrections made so far are listed on the <a href=\"/methods\">methods page</a>.</p>\n      <p class=\"fineprint\">Issues on GitHub are public, so leave personal details out of them.\n      OPAX does not yet have a private contact address. One is coming, and this page will name\n      it.</p>\n\n      <h2 id=\"support-account\">Your account</h2>\n      <ul class=\"about-list\">\n        <li><strong>Signing in.</strong> Enter your email address and OPAX emails you a sign-in\n        link and, when you sign in from the iPhone app (which is in testing), an eight-digit code\n        as well. Each works once and expires after 15 minutes. If nothing arrives, check your\n        spam folder, then ask for a new one. Signing in for the first time creates your account.\n        An account is only needed to take part in the community and to talk to OPAX by voice;\n        everything else works without one. Accounts and voice are for people aged 16 and\n        over.</li>\n        <li><strong>Signing out.</strong> Sign out on one device, or on every device from your\n        account page on the website.</li>\n        <li><strong>Voice.</strong> Each account has 10 minutes of voice in total. Voice needs\n        microphone access, which you can turn on or off in your browser's settings, or for the\n        iPhone app in Settings.</li>\n        <li><strong>Deleting your account.</strong> On the website, open\n        <a href=\"/community?view=delete-account\">Delete your account</a>; if you have signed in\n        to the iPhone app, Delete account under Account does the same. OPAX emails you a fresh\n        code, and entering it deletes your\n        account and what you wrote. It cannot be undone.\n        <a href=\"/privacy#privacy-deletion\">What is deleted and what is kept</a>.</li>\n      </ul>\n\n      <h2 id=\"support-more\">Privacy and the source</h2>\n      <p><a href=\"/privacy\">Privacy</a> sets out what OPAX collects and who receives it.\n      <a href=\"/methods\">Methods</a> explains how the record is built and how to cite it. OPAX's\n      code is open source, at\n      <a href=\"https://github.com/jaketracey/opax\" rel=\"noopener\">github.com/jaketracey/opax</a>.</p>\n    </section>\n\n  </div>\n";if(answer)main.prepend(answer);}})();
